function bio11AddSection(chapterId, section) {
  const chapter = BIO_11_DATA.find(item => item.id === chapterId);
  if (!chapter) throw new Error(`Unknown Biology chapter ${chapterId}`);
  if (!section.source || !section.source.scan) throw new Error(`Biology section ${section.id} needs a source scan number`);
  const current = chapter.sections.find(item => item.id === section.id);
  if (current) Object.assign(current, section);
  else chapter.sections.push(section);
  return section;
}

// Paragraph record: original English text plus aligned Urdu and Pashto translations.
function bio11Pair(original, urdu, pashto, extra = {}) {
  return { original, text: original, urdu, pashto, ...extra };
}

// Compact page builder: paras given as [idSuffix, english, urdu, pashto, extra?].
function bio11Page(chapterId, meta, rows, extras = {}) {
  const prefix = `bio11-s${String(meta.scan).padStart(3, '0')}`;
  const paras = rows.map(row => Array.isArray(row)
    ? bio11Pair(row[1], row[2], row[3], { id: `${prefix}-${row[0]}`, ...(row[4] || {}) })
    : row);
  const section = {
    id: `${prefix}-${meta.slug || 'page'}`,
    title: meta.title, headingUrdu: meta.headingUrdu, headingPashto: meta.headingPashto,
    sourceLanguage: 'en',
    source: { scan: meta.scan, printedPage: meta.printedPage === undefined ? null : meta.printedPage, ...bio11PdfRef(meta.scan) },
    layout: meta.layout || 'sourcePage',
    auditStatus: meta.auditStatus || 'verified against scan',
    paras, ...extras
  };
  return bio11AddSection(chapterId, section);
}

function bio11PdfRef(scan) {
  const hit = BIO_11_SOURCE.pdfRanges.find(([, first, last]) => scan >= first && scan <= last);
  return hit ? { pdf: `bio${hit[0]}.pdf`, pdfPage: scan - hit[1] + 1 } : {};
}

function bio11Safe(value) {
  return typeof sanitize === 'function' ? sanitize(value) : String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

// Scientific notation helpers for source text: subscripts, superscripts and italic genus names.
function bio11SourceText(value) {
  let s = bio11Safe(value);
  s = s.replace(/([A-Za-z0-9\)])_(\d+)/g, '$1<sub>$2</sub>');
  s = s.replace(/\)_n\b/g, ')<sub>n</sub>');
  s = s.replace(/P_(fr|r)/g, 'P<sub>$1</sub>');
  s = s.replace(/\^(\d+|-|\+{1,3}|2-|2\+|3\+)/g, '<sup>$1</sup>');
  s = s.replace(/\*\*([^*]{1,80})\*\*/g, '<b>$1</b>');
  s = s.replace(/\*([^*]{1,60})\*/g, '<i>$1</i>');
  return s;
}

