function bio11RenderWordMeanings(text, sourceId) {
  const terms = Object.keys(bio11WordVocabulary).sort((a, b) => b.length - a.length);
  const pattern = new RegExp('\\b(' + terms.map(term => term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|') + ')\\b', 'gi');
  const src = String(text ?? '');
  let result = '', end = 0, occurrence = 0;
  for (const match of src.matchAll(pattern)) {
    result += bio11SourceText(src.slice(end, match.index));
    const target = String(sourceId || 'bio11').replace(/[^a-zA-Z0-9_-]/g, '-') + '-word-' + (++occurrence);
    const meaning = bio11WordVocabulary[match[0].toLowerCase()];
    result += `<button type="button" class="bio11-word-meaning" popovertarget="${target}" aria-label="${bio11Safe(match[0])}: اردو / پښتو">${bio11Safe(match[0])}</button><span id="${target}" popover class="bio11-word-pop"><strong>${bio11Safe(match[0])}</strong><br><span lang="ur" dir="rtl">${bio11Safe(meaning.ur)}</span><br><span lang="ps" dir="rtl">${bio11Safe(meaning.ps)}</span></span>`;
    end = match.index + match[0].length;
  }
  return result + bio11SourceText(src.slice(end));
}

function bio11RenderPair(p) {
  const id = bio11Safe(p.id || '');
  const original = bio11RenderWordMeanings(p.original, p.id);
  const urdu = bio11SourceText(p.urdu), pashto = bio11SourceText(p.pashto);
  const gap = p.sourceGap ? `<p class="bio11-source-note"><strong>Unresolved source:</strong> ${bio11Safe(p.sourceGap.note)}</p>` : '';
  const editorial = p.editorialNote ? `<p class="bio11-editorial-note"><strong>Editorial clarification:</strong> ${bio11Safe(p.editorialNote)}</p>` : '';
  const tag = p.kind === 'heading' ? 'h4' : p.kind === 'subheading' ? 'h5' : p.kind === 'caption' ? 'figcaption' : 'p';
  const wrapper = p.kind === 'aside' || p.kind === 'tidbit' ? 'aside' : 'article';
  const label = p.kind === 'tidbit' ? '<span class="bio11-tidbit-label">Tidbit</span>' : '';
  const extraClass = p.kind === 'tidbit' ? ' bio11-tidbit' : p.role === 'question' ? ' bio11-question' : p.role === 'answer' ? ' bio11-answer' : '';
  return `<${wrapper} class="bio11-pair${extraClass}" data-source-id="${id}" onclick="bio11TogglePair(event)">${label}<${tag} lang="en">${original}</${tag}><details class="bio11-translations"><summary>English / اردو / پښتو</summary><p lang="ur" dir="rtl">${urdu}</p><p lang="ps" dir="rtl">${pashto}</p></details>${gap}${editorial}</${wrapper}>`;
}

function bio11TogglePair(event) {
  if (!event || !event.currentTarget) return;
  if (event.target.closest('button, details, a')) return;
  const details = event.currentTarget.querySelector(':scope > details.bio11-translations');
  if (details) details.open = !details.open;
}

function bio11RenderParagraphs(paras) {
  let html = '', group = null, tag = 'ul';
  for (const p of paras || []) {
    const next = p.listGroup || null;
    if (group && group !== next) html += `</${tag}>`;
    if (next && group !== next) { tag = p.listType === 'ordered' ? 'ol' : 'ul'; html += tag === 'ol' ? '<ol class="bio11-list bio11-list-ordered">' : '<ul class="bio11-list">'; }
    html += next ? `<li${p.listLabel ? ' class="bio11-labelled" data-label="' + bio11Safe(p.listLabel) + '"' : ''}>${bio11RenderPair(p)}</li>` : bio11RenderPair(p);
    group = next;
  }
  return html + (group ? `</${tag}>` : '');
}

function bio11RenderFigure(f) {
  const translations = f.captionUrdu || f.captionPashto || (f.labels && f.labels.length)
    ? `<details class="bio11-translations"><summary>English / اردو / پښتو</summary>${f.captionUrdu ? `<p lang="ur" dir="rtl">${bio11SourceText(f.captionUrdu)}</p>` : ''}${f.captionPashto ? `<p lang="ps" dir="rtl">${bio11SourceText(f.captionPashto)}</p>` : ''}${(f.labels || []).map(label => `<p class="bio11-label-row"><span lang="en">${bio11SourceText(label.en)}</span> · <span lang="ur" dir="rtl">${bio11SourceText(label.ur)}</span> · <span lang="ps" dir="rtl">${bio11SourceText(label.ps)}</span></p>`).join('')}</details>` : '';
  return `<figure class="bio11-figure" data-source-id="${bio11Safe(f.id || '')}">${f.svg || ''}<figcaption>${bio11SourceText(f.caption || '')}${translations}${f.sourceGap ? `<p class="bio11-source-note">Unresolved source: ${bio11Safe(f.sourceGap.note)}</p>` : ''}</figcaption></figure>`;
}

function bio11Cell(en, ur = '', ps = '') { return { en: String(en), ur: String(ur), ps: String(ps) }; }

function bio11RenderTable(table) {
  const cell = c => typeof c === 'string' ? { en: c, ur: '', ps: '' } : c;
  const cellHtml = (c, tagName) => { const v = cell(c); const tr = v.ur || v.ps ? `<details class="bio11-cell-translations"><summary>ترجمہ</summary><span lang="ur" dir="rtl">${bio11SourceText(v.ur)}</span><br><span lang="ps" dir="rtl">${bio11SourceText(v.ps)}</span></details>` : ''; return `<${tagName}${tagName === 'th' ? ' scope="col"' : ''}>${bio11SourceText(v.en)}${tr}</${tagName}>`; };
  const caption = `<caption>${bio11SourceText(table.caption || '')}${table.captionUrdu || table.captionPashto ? `<details class="bio11-translations"><summary>English / اردو / پښتو</summary><span lang="ur" dir="rtl">${bio11SourceText(table.captionUrdu || '')}</span><br><span lang="ps" dir="rtl">${bio11SourceText(table.captionPashto || '')}</span></details>` : ''}</caption>`;
  const head = table.headers && table.headers.length ? `<thead><tr>${table.headers.map(h => cellHtml(h, 'th')).join('')}</tr></thead>` : '';
  const body = `<tbody>${(table.rows || []).map(row => `<tr>${row.map(c => cellHtml(c, 'td')).join('')}</tr>`).join('')}</tbody>`;
  return `<div class="bio11-table-wrap" data-source-id="${bio11Safe(table.id || '')}"><table class="bio11-table">${caption}${head}${body}</table>${table.sourceGap ? `<p class="bio11-source-note">Unresolved source: ${bio11Safe(table.sourceGap.note)}</p>` : ''}</div>`;
}

function bio11RenderSectionBody(sec) {
  if (!sec.flow) {
    return bio11RenderParagraphs(sec.paras)
      + (sec.tables || []).map(bio11RenderTable).join('')
      + (sec.figures || []).map(bio11RenderFigure).join('');
  }
  return sec.flow.map(block => {
    if (block.type === 'paragraphs') return bio11RenderParagraphs(block.ids.map(id => (sec.paras || []).find(p => p.id === id)).filter(Boolean));
    if (block.type === 'figure') return sec.figures && sec.figures[block.index] ? bio11RenderFigure(sec.figures[block.index]) : '';
    if (block.type === 'table') return sec.tables && sec.tables[block.index] ? bio11RenderTable(sec.tables[block.index]) : '';
    if (block.type === 'html') return block.html || '';
    return '';
  }).join('');
}

function bio11SectionHeader(sec) {
  const src = sec.source || {};
  const ref = [`Scan ${src.scan}`, src.printedPage ? `Printed page ${src.printedPage}` : 'unnumbered', src.pdf ? `${src.pdf} page ${src.pdfPage}` : ''].filter(Boolean).join(' · ');
  const status = String(sec.auditStatus || '').startsWith('verified') ? ' · Source checked' : '';
  return `<h3>${bio11SourceText(sec.title)}<span class="bio11-heading-translations"><span lang="ur" dir="rtl">${bio11SourceText(sec.headingUrdu || '')}</span><span lang="ps" dir="rtl">${bio11SourceText(sec.headingPashto || '')}</span></span></h3><p class="bio11-source-ref">${ref}${status}</p>${sec.sourceNote ? `<p class="bio11-source-note"><strong>Source review note:</strong> ${bio11Safe(sec.sourceNote)}</p>` : ''}`;
}

function bio11FilterSectionsForTab(sections, tabId) {
  const isExercise = p => p.role === 'question' || p.role === 'answer' || p.role === 'option' || p.exerciseId;
  if (tabId === 'lesson') return sections;
  if (tabId === 'slos') return sections.filter(sec => sec.layout === 'outcomes');
  if (tabId === 'concepts') return sections.filter(sec => sec.layout !== 'outcomes' && sec.layout !== 'exercise').map(sec => ({ ...sec, flow: undefined, figures: [], tables: [], paras: (sec.paras || []).filter(p => p.kind === 'heading' || p.kind === 'subheading' || p.kind === 'definition' || p.kind === 'tidbit' || p.concept) })).filter(sec => sec.paras.length);
  if (tabId === 'exercise') return sections.map(sec => {
    const paras = (sec.paras || []).filter(isExercise);
    return { ...sec, flow: undefined, figures: (sec.figures || []).filter(f => f.exerciseId), tables: (sec.tables || []).filter(t => t.exerciseId), paras };
  }).filter(sec => sec.paras.length || sec.figures.length || sec.tables.length);
  if (tabId === 'formulas') return sections.map(sec => ({ ...sec, flow: undefined, paras: (sec.paras || []).filter(p => p.summary || sec.layout === 'summary'), figures: sec.figures || [], tables: sec.tables || [] })).filter(sec => sec.paras.length || sec.figures.length || sec.tables.length);
  return [];
}

function renderBiology11Tab(ch, tabId) {
  const bio11Key = sec => (typeof sec.source.printedPage === 'number' ? sec.source.printedPage : sec.source.scan);
  const all = [...(ch.sections || [])].sort((a, b) => (bio11Key(a) - bio11Key(b)) || (a.source.scan - b.source.scan));
  const sections = bio11FilterSectionsForTab(all, tabId || 'lesson');
  if (!all.length) return `<div class="bio11-reader"><p class="bio11-source-note">Source comparison has not reached this chapter yet. ${bio11Safe(ch.pageRange || '')}.</p></div>`;
  if (!sections.length) return '<div class="bio11-reader"><p>No records of this kind exist on the reviewed pages of this chapter yet.</p></div>';
  const draft = sections.some(sec => !String(sec.auditStatus || '').startsWith('verified'));
  const part = ch.part ? `<p class="bio11-part">${bio11Safe(ch.part)} · <span lang="ur" dir="rtl">${bio11Safe(ch.partUrdu || '')}</span> · <span lang="ps" dir="rtl">${bio11Safe(ch.partPashto || '')}</span></p>` : '';
  const chapterGap = ch.sourceGap ? `<p class="bio11-source-note"><strong>Source gap:</strong> ${bio11Safe(ch.sourceGap)}</p>` : '';
  return `<div class="bio11-reader">${part}${chapterGap}${draft ? '<p class="bio11-source-note">This view includes draft or unresolved source records. Page-specific notes identify known gaps.</p>' : ''}${sections.map(sec => `<section class="bio11-page" data-source-scan="${sec.source.scan}">${bio11SectionHeader(sec)}${bio11RenderSectionBody(sec)}</section>`).join('')}</div>`;
}

function biology11SourceSearchText(ch) {
  return [ch.title, ch.titleUrdu, ch.titlePashto, ...(ch.sections || []).flatMap(sec => [
    sec.title, sec.headingUrdu, sec.headingPashto,
    ...(sec.paras || []).flatMap(p => [p.original, p.urdu, p.pashto]),
    ...(sec.figures || []).flatMap(f => [f.caption, f.captionUrdu, f.captionPashto]),
    ...(sec.tables || []).flatMap(t => [t.caption, ...(t.rows || []).flat().map(c => typeof c === 'string' ? c : c.en)])
  ])].filter(Boolean).join(' ');
}

