  flow: [{ type: 'paragraphs', ids: ['bio11-s006-h-intro', 'bio11-s006-p1', 'bio11-s006-p2', 'bio11-s006-theory-1', 'bio11-s006-theory-2', 'bio11-s006-theory-3', 'bio11-s006-theory-4', 'bio11-s006-tidbit', 'bio11-s006-h-1-1', 'bio11-s006-p3'] }, { type: 'table', index: 0 }, { type: 'paragraphs', ids: ['bio11-s006-h-1-1-1', 'bio11-s006-p4'] }]
