function bio11FigCellWallBlock() {
  const cell = (x, y) => `<path d="M${x} ${y} l34 -16 l36 14 l0 36 l-34 16 l-36 -14 Z" fill="#2f6b3a" stroke="#1b4d2a" stroke-width="2"/><path d="M${x + 12} ${y + 8} l22 -9 l22 9 l0 22 l-22 9 l-22 -9 Z" fill="#8fbf8a" stroke="#1b4d2a"/><ellipse cx="${x + 34}" cy="${y + 15}" rx="11" ry="6" fill="#e7e5e4" stroke="#57534e"/>`;
  return `<svg viewBox="0 0 420 330" role="img" aria-labelledby="bio11-fig-1-3-title bio11-fig-1-3-desc" style="width:100%;max-width:420px;height:auto"><title id="bio11-fig-1-3-title">Fig 1.3 Cell wall</title><desc id="bio11-fig-1-3-desc">Block of plant cells showing, from outside to inside, the middle lamella between neighbouring cells, the primary wall, the secondary wall and the plasma membrane lining the protoplast.</desc>
<path d="M20 150 q40 -60 150 -50 q60 6 110 40 l0 120 q-60 40 -130 24 q-90 -12 -130 -70 Z" fill="#35703f" stroke="#1b4d2a" stroke-width="3"/>
${cell(60, 145)}${cell(135, 120)}${cell(95, 215)}${cell(185, 190)}${cell(40, 195)}
<g font-size="17" fill="#111"><text x="280" y="62">Plasma</text><text x="280" y="82">membrane</text><text x="280" y="124">Middle</text><text x="280" y="144">Lamella</text><text x="270" y="190">Secondary</text><text x="270" y="210">wall</text><text x="270" y="250">Primary</text><text x="270" y="270">wall</text></g>
<g stroke="#111" stroke-width="1.6" fill="none"><path d="M276 76 L196 150"/><path d="M276 132 L210 175"/><path d="M266 196 L225 206"/><path d="M266 256 L225 232"/></g>
<text x="40" y="318" font-size="18" font-weight="700" fill="#b91c4b">Fig 1.3 Cell wall</text></svg>`;
}

