// Shared SVG callout helper: labels = [{t:'text', x, y, a:'start'|'end'|'middle', to:[x2,y2]}]
function bio11Callouts(labels, size = 13) {
  return `<g font-size="${size}" fill="#111">${labels.map(l => `<text x="${l.x}" y="${l.y}" text-anchor="${l.a || 'start'}">${l.t.split('|').map((s, i) => `<tspan x="${l.x}" dy="${i ? size + 2 : 0}">${s}</tspan>`).join('')}</text>`).join('')}</g><g stroke="#111" stroke-width="1.3" fill="none">${labels.filter(l => l.to).map(l => `<path d="M${l.from ? l.from[0] : l.x} ${l.from ? l.from[1] : l.y + 3} L${l.to[0]} ${l.to[1]}"/>`).join('')}</g>`;
}
function bio11Svg(id, vb, title, desc, body, style = '') {
  return `<svg viewBox="${vb}" role="img" aria-labelledby="${id}-title ${id}-desc" style="width:100%;max-width:820px;height:auto;${style}"><title id="${id}-title">${title}</title><desc id="${id}-desc">${desc}</desc>${body}</svg>`;
}

