function bio11FigRibosomes() {
  const body = `<path d="M60 70 q20 -40 130 -30 q20 30 -10 44 q-40 0 -60 14 q-30 6 -60 -28 Z" fill="#fde68a" stroke="#a16207" stroke-width="2.5"/>
<path d="M60 180 q-20 30 60 40 q40 -6 70 -30 q20 -20 -10 -34 q-20 -8 -40 6 q-30 4 -80 18 Z" fill="#bfdbfe" stroke="#1d4ed8" stroke-width="2.5"/>
<path d="M455 52 q70 -38 160 -10 q30 20 -20 40 q-70 20 -130 -4 Z" fill="#fbbf24" stroke="#a16207" stroke-width="2.5"/>
<path d="M440 120 q10 -34 80 -30 q40 -4 70 -2 q50 10 30 50 q-40 30 -100 10 q-20 16 -60 -4 q-20 -10 -20 -24 Z" fill="#7aa3d6" stroke="#1d4ed8" stroke-width="2.5"/>
<path d="M300 110 H400" stroke="#111" stroke-width="2" marker-end="url(#bio11-rb-arrow)"/>
<defs><marker id="bio11-rb-arrow" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto"><path d="M0 0L9 4.5L0 9Z" fill="#111"/></marker></defs>
${bio11Callouts([{ t: 'Small subunits', x: 280, y: 52, to: [200, 60], from: [276, 56] }, { t: 'Large subunits', x: 270, y: 210, to: [190, 190], from: [268, 206] }], 15)}`;
  return bio11Svg('bio11-fig-1-8', '0 0 700 270', 'Fig 1.8 Ribosomes', 'A ribosome is built from two subunits. A small subunit (top) and a large subunit (bottom) are shown separately on the left and together as the assembled ribosome on the right, joined by an arrow.', body, 'background:#fff;border:1px solid #111');
}

