    labels: [['cis face', 'cis سطح', 'cis مخ'], ['incoming transport vesicle', 'آنے والی نقل و حمل کی تھیلی', 'راتلونکې د لېږد کڅوړه'], ['lumen', 'لیومن (اندرونی خلا)', 'لیومن (داخلي تشه)'], ['cisternae', 'سسٹرنی', 'سیسټرني'], ['trans face', 'trans سطح', 'trans مخ'], ['newly forming vesicle', 'نئی بننے والی تھیلی', 'نوې جوړېدونکې کڅوړه'], ['secretory vesicle', 'افرازی تھیلی', 'ترشحي کڅوړه']].map(([en, ur, ps]) => ({ en, ur, ps }))
