  flow: [{ type: 'paragraphs', ids: ['bio11-s018-p0', 'bio11-s018-p1'] }, { type: 'figure', index: 0 }, { type: 'paragraphs', ids: ['bio11-s018-h-a', 'bio11-s018-p2', 'bio11-s018-p3', 'bio11-s018-h-v', 'bio11-s018-p4'] }, { type: 'figure', index: 1 }],
