function bio11FigCentrioles() {
  const tube = (x, y, a, len) => `<g transform="translate(${x} ${y}) rotate(${a})"><rect x="0" y="-9" width="${len}" height="18" rx="9" fill="#d97706" stroke="#7c2d12" stroke-width="1.4"/><ellipse cx="0" cy="0" rx="6" ry="9" fill="#fbbf24" stroke="#7c2d12"/><rect x="4" y="-5" width="${len - 12}" height="4" fill="#fcd34d" opacity=".6"/></g>`;
  const ring = (cx, cy, a, len) => Array.from({ length: 9 }, (_, i) => { const t = i * 40 * Math.PI / 180; return tube(cx + 46 * Math.cos(t) * Math.sin(a), cy + 46 * Math.sin(t), a * 0, len); }).join('');
  const bundle = (x0, y0, ang, n, len) => Array.from({ length: n }, (_, i) => tube(x0 + (i % 3) * 5, y0 + i * 14, ang, len)).join('');
  const body = `<polygon points="150,260 330,120 560,300 360,420" fill="#7dd3fc" opacity=".55" stroke="#0369a1"/><polygon points="250,100 330,360 520,200" fill="#38bdf8" opacity=".45" stroke="#0369a1"/>
<g>${bundle(160, 190, 28, 9, 270)}${bundle(210, 90, -32, 9, 240)}${bundle(300, 270, 24, 9, 300)}${bundle(360, 140, 20, 6, 260)}</g>
<line x1="340" y1="250" x2="400" y2="270" stroke="#7dd3fc" stroke-width="8"/>
${bio11Callouts([{ t: 'centriole pair', x: 540, y: 120, to: [420, 160], from: [538, 124] }, { t: 'microtubule|triplet', x: 560, y: 360, to: [500, 320], from: [558, 330] }], 15)}`;
  return bio11Svg('bio11-fig-1-13', '0 0 700 450', 'Fig 1.13 Centrioles', 'A pair of centrioles placed at right angles to each other. Each centriole is a hollow cylinder built from nine microtubule triplets arranged in a ring.', body, 'background:#fff;border:1px solid #111');
}
function bio11FigCentrioleCross() {
  const ring = Array.from({ length: 9 }, (_, i) => { const t = i * 40 * Math.PI / 180, x = 110 + 62 * Math.cos(t), y = 110 + 62 * Math.sin(t), d = 180 / Math.PI * t + 90; return `<g transform="translate(${x} ${y}) rotate(${d + 30})"><circle cx="-7" cy="0" r="6.5" fill="#fbbf24" stroke="#7c2d12"/><circle cx="7" cy="0" r="6.5" fill="#fbbf24" stroke="#7c2d12"/><circle cx="0" cy="-10" r="6.5" fill="#fbbf24" stroke="#7c2d12"/></g>`; }).join('');
  return bio11Svg('bio11-fig-1-13b', '0 0 220 220', 'Centriole cross section (9 triplets)', 'Cross section of one centriole: a ring of nine microtubule triplets, each triplet made of three fused tubules.', `<circle cx="110" cy="110" r="95" fill="#f1f5f9" stroke="#94a3b8"/>${ring}<circle cx="110" cy="110" r="10" fill="#cbd5e1" stroke="#64748b"/>`, 'max-width:220px');
}

