function bio11FigCilia() {
  const doublets = (cx, cy, r) => Array.from({ length: 9 }, (_, i) => { const t = i * 40 * Math.PI / 180; return `<ellipse cx="${cx + r * Math.cos(t)}" cy="${cy + r * Math.sin(t)}" rx="8" ry="7" fill="#dc2626" stroke="#7f1d1d" stroke-width="1.4" transform="rotate(${i * 40} ${cx + r * Math.cos(t)} ${cy + r * Math.sin(t)})"/><ellipse cx="${cx + (r - 9) * Math.cos(t)}" cy="${cy + (r - 9) * Math.sin(t)}" rx="5" ry="4" fill="#ef4444" stroke="#7f1d1d" stroke-width="1"/>`; }).join('');
  const body = `<path d="M110 360 q10 -120 60 -150 q60 -40 70 -130 q10 -40 60 -30 q50 20 20 70 q-30 80 -20 130 q10 60 40 110 L110 360 Z" fill="#4a7fb8" stroke="#1e3a8a" stroke-width="2"/>
<path d="M60 420 q70 -50 150 -60 L230 440 q-100 0 -170 -20 Z" fill="#2a5a94" stroke="#1e3a8a" stroke-width="2"/>
<rect x="150" y="360" width="50" height="70" fill="#9b1c1c" stroke="#450a0a"/>
<ellipse cx="265" cy="70" rx="46" ry="36" fill="#e8f0fa" stroke="#1e3a8a" stroke-width="2"/>${doublets(265, 70, 22)}<circle cx="265" cy="70" r="6" fill="#dc2626"/>
<ellipse cx="610" cy="305" rx="150" ry="130" fill="#6b8fb5" stroke="#1e3a8a" stroke-width="2"/>
<ellipse cx="610" cy="280" rx="130" ry="110" fill="#d6e4f0" stroke="#1e3a8a" stroke-width="2"/>${doublets(610, 280, 70)}
<circle cx="610" cy="280" r="9" fill="#dc2626"/><circle cx="600" cy="278" r="5" fill="#ef4444"/>
<g stroke="#a16207" stroke-width="1.2">${Array.from({ length: 9 }, (_, i) => { const t = i * 40 * Math.PI / 180; return `<line x1="610" y1="280" x2="${610 + 62 * Math.cos(t)}" y2="${280 + 62 * Math.sin(t)}"/>`; }).join('')}</g>
${bio11Callouts([{ t: 'Outer|Microtubule|Doublet', x: 330, y: 70, to: [282, 74], from: [326, 74] }, { t: 'Central|Microtubule|(Axoneme)', x: 720, y: 108, to: [612, 280], from: [730, 140] }, { t: 'Plasma|Membrane', x: 290, y: 200, a: 'end', to: [270, 190], from: [292, 194] }], 18)}`;
  return bio11Svg('bio11-fig-1-14', '0 0 840 470', 'Fig 1.14 Internal organization of cilia', 'A cilium rising from the cell surface, enclosed by the plasma membrane. Cut across, it shows the axoneme: nine outer doublet microtubules surrounding a central pair of single microtubules.', body, 'background:#fff;border:1px solid #111');
}

