    id: 'bio11-fig-1-16', svg: bio11FigChloroplastLocation(), caption: 'Fig 1.16 Location and structure of Chloroplast', captionUrdu: 'شکل ۱.۱۶ کلوروپلاسٹ کا مقام اور ساخت', captionPashto: 'شکل ۱.۱۶ د کلوروپلاسټ ځای او جوړښت',
    labels: [['Vascular bundle', 'عروقی بنڈل', 'ناقلې ټولګه'], ['Cuticle', 'کیوٹیکل', 'کیوټیکل'], ['Epidermis', 'بشرہ', 'پوستکی'], ['Palisade cell', 'پیلیسیڈ خلیہ', 'پیلیسېډ حجره'], ['Stoma', 'روزن (سٹوما)', 'سټوما'], ['Spongy cell', 'سپنجی خلیہ', 'سپنجي حجره'], ['Chloroplast', 'کلوروپلاسٹ', 'کلوروپلاسټ'], ['Nucleus', 'مرکزہ', 'هسته'], ['Vacuole', 'خلا (ویکیول)', 'واکیول'], ['Cell Wall', 'خلوی دیوار', 'حجروي دیوال'], ['Outer Membrane', 'بیرونی جھلی', 'بهرنۍ غشا'], ['Inner Membrane', 'اندرونی جھلی', 'داخلي غشا'], ['Thylakoid', 'تھائلکوئڈ', 'تایلاکوئید'], ['Stroma', 'سٹروما', 'سټروما'], ['Granum', 'گرینم', 'ګرانم']].map(([en, ur, ps]) => ({ en, ur, ps }))
