function bio11FigNucleus() {
  const pores = Array.from({ length: 26 }, (_, i) => { const t = (i * 13.8 - 60) * Math.PI / 180; return `<circle cx="${300 + 118 * Math.cos(t)}" cy="${190 + 118 * Math.sin(t)}" r="4" fill="#0b3b4a" stroke="#fff" stroke-width="1"/>`; }).join('');
  const body = `<circle cx="300" cy="190" r="125" fill="#3b82a0" stroke="#164e63" stroke-width="3"/>
<circle cx="300" cy="190" r="112" fill="#7fb2c7" stroke="#164e63" stroke-width="1.5"/>
<path d="M300 190 L300 70 A120 120 0 0 0 180 190 Z" fill="#0f2f3a"/>
<circle cx="300" cy="190" r="100" fill="#9ec3d1" opacity=".0"/>
<path d="M300 190 m-98 0 a98 98 0 0 1 98 -98 v98 Z" fill="#cfe3ec" stroke="#164e63"/>
<g fill="#6aa0b8" stroke="#164e63" stroke-width="1">${Array.from({ length: 70 }, (_, i) => `<circle cx="${300 - 90 + (i * 53) % 88}" cy="${190 - 90 + (i * 37) % 88}" r="2.2"/>`).join('')}</g>
<circle cx="268" cy="178" r="42" fill="#b4185f" stroke="#500724" stroke-width="2.4"/><circle cx="262" cy="172" r="26" fill="#d6336f" opacity=".7"/>
<g>${pores}</g>
${bio11Callouts([{ t: 'Chromatin', x: 20, y: 56, to: [260, 100], from: [100, 62] }, { t: 'Nucleolus', x: 30, y: 218, to: [255, 192], from: [100, 214] }, { t: 'Nuclear|pores', x: 470, y: 150, to: [418, 142], from: [466, 146] }, { t: 'Nuclear|envelope', x: 450, y: 280, to: [410, 260], from: [446, 276] }], 17)}`;
  return bio11Svg('bio11-fig-1-17', '0 0 560 380', 'Fig: 1.17 Parts of a nucleus', 'A cut-away nucleus. The double nuclear envelope is perforated by nuclear pores. Inside lie the dark nucleolus and the chromatin threads suspended in nucleoplasm.', body, 'background:#fff;border:1px solid #111');
}

