function bio11FigCondensation() {
  // Structural formulas: amino acid + amino acid -> dipeptide + H2O (water in blue).
  const T = (x, y, s, c = '#111') => `<text x="${x}" y="${y + 7}" font-size="21" font-weight="700" fill="${c}" text-anchor="middle">${s}</text>`;
  const L = (x1, y1, x2, y2, c = '#111') => `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${c}" stroke-width="2.2"/>`;
  const D = (x, y1, y2, c = '#111') => `${L(x - 3, y1, x - 3, y2, c)}${L(x + 3, y1, x + 3, y2, c)}`;
  // Backbone atoms along the baseline y: N at x, C-alpha at x+60, C at x+120.
  const N = (x, y, withLeftH, nitrogenLabel = 'N') => `${T(x, y, nitrogenLabel, '#c11')}${withLeftH ? `${T(x - 44, y, 'H')}${L(x - 32, y, x - 14, y)}` : ''}${L(x, y + 12, x, y + 40)}${T(x, y + 52, 'H')}`;
  const CA = (x, y) => `${T(x, y, 'C')}${L(x - 12, y, x - 14 + 0, y)}${L(x, y - 12, x, y - 40)}${T(x, y - 52, 'R')}${L(x, y + 12, x, y + 40)}${T(x, y + 52, 'H')}`;
  const CO = (x, y) => `${T(x, y, 'C')}${D(x, y - 14, y - 40)}${T(x, y - 52, 'O', '#c11')}`;
  const bond = (x1, x2, y) => L(x1 + 14, y, x2 - 14, y);
  const y = 170;
  const aaBlock = x => `${N(x, y, true)}${bond(x, x + 60, y)}${CA(x + 60, y)}${bond(x + 60, x + 120, y)}${CO(x + 120, y)}${bond(x + 120, x + 180, y)}${T(x + 180, y, 'O', '#c11')}${bond(x + 180, x + 226, y)}${T(x + 226, y, 'H')}`;
  const dip = x => `${N(x, y, true)}${bond(x, x + 60, y)}${CA(x + 60, y)}${bond(x + 60, x + 120, y)}${CO(x + 120, y)}${bond(x + 120, x + 180, y)}${N(x + 180, y, false)}${bond(x + 180, x + 240, y)}${CA(x + 240, y)}${bond(x + 240, x + 300, y)}${CO(x + 300, y)}${bond(x + 300, x + 360, y)}${T(x + 360, y, 'O', '#c11')}${bond(x + 360, x + 406, y)}${T(x + 406, y, 'H')}`;
  const water = x => `${T(x, y - 4, 'O', '#1d4ed8')}${L(x - 8, y + 8, x - 22, y + 30, '#1d4ed8')}${L(x + 8, y + 8, x + 22, y + 30, '#1d4ed8')}${T(x - 28, y + 42, 'H', '#1d4ed8')}${T(x + 28, y + 42, 'H', '#1d4ed8')}`;
  const body = `<defs><marker id="bio11-cd-a" markerWidth="10" markerHeight="10" refX="9" refY="5" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#111"/></marker></defs>
${aaBlock(70)}${T(335, y, '+', '#333')}${aaBlock(420)}
<path d="M690 ${y} H760" stroke="#111" stroke-width="3" marker-end="url(#bio11-cd-a)"/>
${dip(830)}${T(1306, y, '+', '#333')}${water(1360)}
<path d="M1250 ${y - 4} q30 -50 110 -30" fill="none" stroke="#1d4ed8" stroke-width="1.5" stroke-dasharray="4 3" opacity=".01"/>`;
  return bio11Svg('bio11-fig-2-1', '0 0 1420 300', 'Fig: 2.1 Example of condensation reaction', 'Two amino acids, each H2N–CHR–COOH, join: the OH of the first carboxyl group and an H of the second amino group are removed as water (shown in blue), leaving the dipeptide H2N–CHR–CO–NH–CHR–COOH with a new peptide bond.', body, 'background:#fff');
}

