  const water = (x, y, k, id) => `${sph(x, y, 20 * k, '#f87171', '#991b1b', id + 'o')}${sph(x - 18 * k, y - 22 * k, 13 * k, '#ffffff', '#cbd5e1', id + 'a')}${sph(x + 16 * k, y - 24 * k, 13 * k, '#ffffff', '#cbd5e1', id + 'b')}`;
