// Shared sugar-structure drawing helpers (labels preserved from the scans).
function bio11SugarText(x, y, s, a = 'middle', sz = 18) { return `<text x="${x}" y="${y + 6}" font-size="${sz}" fill="#111" text-anchor="${a}" font-family="Arial,sans-serif">${s}</text>`; }
function bio11SugarLine(x1, y1, x2, y2, w = 1.8) { return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="#111" stroke-width="${w}"/>`; }
// Six-membered (pyranose) ring: ring O at top right. labels: {tl: [..], ...} given as arrays [text, dx, dy]
function bio11Pyranose(cx, cy, s, subs, bold = false) {
  const p = [[cx - s, cy], [cx - s / 2, cy - s * 0.8], [cx + s / 2, cy - s * 0.8], [cx + s, cy], [cx + s / 2, cy + s * 0.8], [cx - s / 2, cy + s * 0.8]];
  const ring = `<polygon points="${p.map(q => q.join(',')).join(' ')}" fill="${bold ? '#cfe8f3' : 'none'}" stroke="#111" stroke-width="${bold ? 2.2 : 1.6}"/>`;
  const oAt = bio11SugarText(p[2][0] + 10, p[2][1] - 6, 'O');
  return ring + oAt + subs.map(([t, x, y, lx, ly]) => `${bio11SugarText(x, y, t)}${lx !== undefined ? bio11SugarLine(lx, ly, x, y + (y > ly ? -10 : 10)) : ''}`).join('');
}
function bio11Furanose(cx, cy, s, subs) {
  const p = [[cx, cy - s], [cx + s * 0.95, cy - s * 0.3], [cx + s * 0.6, cy + s * 0.8], [cx - s * 0.6, cy + s * 0.8], [cx - s * 0.95, cy - s * 0.3]];
  return `<polygon points="${p.map(q => q.join(',')).join(' ')}" fill="none" stroke="#111" stroke-width="1.8"/>${bio11SugarText(cx, cy - s - 2, 'O')}` + subs.map(([t, x, y]) => bio11SugarText(x, y, t)).join('');
}

