  const ring6 = (cx, cy, r, f = 'none') => `<polygon points="${[0, 1, 2, 3, 4, 5].map(i => `${cx + r * Math.cos(Math.PI / 3 * i + Math.PI / 6)},${cy + r * Math.sin(Math.PI / 3 * i + Math.PI / 6)}`).join(' ')}" fill="${f}" stroke="#111" stroke-width="2"/>`;
  const ring5 = (cx, cy, r) => `<polygon points="${[0, 1, 2, 3, 4].map(i => `${cx + r * Math.cos(2 * Math.PI / 5 * i + Math.PI / 10)},${cy + r * Math.sin(2 * Math.PI / 5 * i + Math.PI / 10)}`).join(' ')}" fill="none" stroke="#111" stroke-width="2"/>`;
  const pyr = (cx, cy, tag, topA, topB, color) => `${ring6(cx, cy, 44)}${T(cx + 56, cy + 34, 'N', 'middle', 16, '#111', 700)}${T(cx + 64, cy - 36, topA || '', 'middle', 16)}${T(cx - 56, cy - 36, topB || '', 'middle', 16)}${T(cx, cy + 96, tag, 'middle', 24, color, 700)}`;
  const body = `<rect x="4" y="4" width="1100" height="640" fill="#fff" stroke="#111" stroke-width="2"/>
<line x1="360" y1="14" x2="360" y2="560" stroke="#111" stroke-width="4" stroke-dasharray="14 8"/>
${T(150, 36, 'Purines', 'middle', 26, '#b0176b', 700)}${T(570, 36, 'Pyrimidines', 'middle', 26, '#b0176b', 700)}
${ring6(240, 170, 48)}${ring5(150, 164, 36)}${T(262, 94, 'H–N–H', 'middle', 16)}${T(110, 160, 'H–', 'end', 16)}${T(284, 220, 'N', 'middle', 16, '#111', 700)}${T(190, 220, 'N', 'middle', 16, '#111', 700)}${T(160, 240, 'H', 'middle', 16)}${T(140, 186, 'N', 'middle', 16, '#111', 700)}${T(330, 210, 'H', 'middle', 16)}${T(240, 280, 'Adenine', 'middle', 24, '#b0176b', 700)}
${ring6(240, 400, 48)}${ring5(150, 394, 36)}${T(260, 330, 'O', 'middle', 16)}${T(310, 360, 'N–H', 'middle', 16)}${T(300, 440, 'N–H', 'middle', 16)}${T(330, 470, 'H', 'middle', 16)}${T(120, 394, 'H–', 'end', 16)}${T(150, 450, 'H', 'middle', 16)}${T(240, 520, 'Guanine', 'middle', 24, '#b0176b', 700)}
${ring6(560, 180, 46)}${T(520, 140, 'N', 'middle', 15)}${T(616, 130, 'H–N–H', 'middle', 15)}${T(560, 270, 'Cytosine', 'middle', 24, '#b0176b', 700)}${T(450, 110, 'H–N–H', 'middle', 15)}
${ring6(760, 130, 44)}${T(764, 66, 'O', 'middle', 16)}${T(722, 82, 'H<tspan font-size="10" dy="4">3</tspan><tspan dy="-4">C–</tspan>', 'middle', 16)}${T(826, 96, 'N–H', 'middle', 15)}${T(780, 220, 'Thymine', 'middle', 24, '#b0176b', 700)}
<circle cx="860" cy="380" r="86" fill="none" stroke="#c0392b" stroke-width="3"/>${ring6(860, 380, 44)}${T(862, 306, 'O', 'middle', 16)}${T(820, 330, 'H–', 'middle', 15)}${T(920, 346, 'N–H', 'middle', 15)}${T(880, 480, 'Uracil', 'middle', 24, '#b0176b', 700)}
${T(500, 520, 'Uracil is only in RNA', 'middle', 18, '#111', 700)}${T(500, 544, 'where it is found', 'middle', 18, '#111', 700)}${T(540, 568, 'instead of thymine (T). It is not', 'middle', 18, '#111', 700)}${T(450, 592, 'part of DNA.', 'middle', 18, '#111', 700)}`;
  return bio11Svg('bio11-fig-2-17b', '0 0 1110 650', 'Fig: 2.17 Chemical structures (purines and pyrimidines)', 'Purines (double-ring): adenine and guanine. Pyrimidines (single-ring): cytosine, thymine and uracil. Uracil is circled: it occurs only in RNA instead of thymine and is not part of DNA.', body, 'background:#fff');
