function bio11FigATPHydrolysis() {
  const T = (x, y, s, a = 'middle', sz = 18, c = '#111', w = 400) => `<text x="${x}" y="${y + 6}" font-size="${sz}" font-weight="${w}" fill="${c}" text-anchor="${a}" font-family="Arial,sans-serif">${s}</text>`;
  const adenosine = (x, y) => `<rect x="${x}" y="${y}" width="190" height="150" fill="#f7f6e4" stroke="#111" stroke-width="2"/><polygon points="${x + 30},${y + 80} ${x + 60},${y + 60} ${x + 90},${y + 80} ${x + 90},${y + 112} ${x + 60},${y + 130} ${x + 30},${y + 112}" fill="none" stroke="#111" stroke-width="2.4"/><polygon points="${x + 90},${y + 70} ${x + 130},${y + 74} ${x + 140},${y + 110} ${x + 110},${y + 130} ${x + 84},${y + 108}" fill="none" stroke="#111" stroke-width="2.4"/><polygon points="${x + 120},${y + 112} ${x + 150},${y + 120} ${x + 170},${y + 144} ${x + 120},${y + 150}" fill="#f3d9ee" stroke="#111" stroke-width="2.4"/>${T(x + 30, y + 22, 'Adenosine', 'start', 20)}`;
  const pBox = (x, y, w, n, label) => `<rect x="${x}" y="${y}" width="${w}" height="150" fill="#f7f6e4" stroke="#111" stroke-width="2"/>${T(x + 14, y + 22, label, 'start', 20)}${Array.from({ length: n }, (_, i) => `<circle cx="${x + 34 + i * 38}" cy="${y + 78}" r="14" fill="#fff" stroke="#111" stroke-width="2"/>${T(x + 34 + i * 38, y + 78, 'P', 'middle', 18)}`).join('')}<path d="M${x - 6} ${y + 78} H${x + 14}" stroke="#111" stroke-width="2"/>`;
  const body = `<rect x="4" y="4" width="1100" height="340" fill="#f1f0d4"/>
${adenosine(20, 24)}${pBox(210, 24, 190, 3, 'Triphosphate')}
<path d="M420 100 H570 M570 100 l-10 -8 M420 112 H570 M420 112 l10 8" stroke="#111" stroke-width="3" fill="none"/>
${adenosine(600, 24)}${pBox(790, 24, 130, 2, 'Diphosphate')}${T(940, 100, '+', 'middle', 22)}<circle cx="990" cy="100" r="16" fill="#fff" stroke="#111" stroke-width="2"/>${T(990, 100, 'P', 'middle', 20)}${T(1050, 100, '-7Kcal', 'middle', 20)}${T(1020, 36, 'Phosphate', 'middle', 18)}
<rect x="20" y="190" width="1060" height="30" fill="#fff" stroke="#111" stroke-width="2"/>${T(210, 205, 'ATP', 'middle', 20)}${T(780, 205, 'ADP', 'middle', 20)}${T(960, 205, '+', 'middle', 20)}${T(1010, 205, '(P)+ Energy', 'start', 20)}
<path d="M420 202 H570 M570 202 l-10 -7 M420 210 H570 M420 210 l10 7" stroke="#111" stroke-width="3" fill="none"/>
${T(30, 250, 'ATP Reaction', 'start', 19)}`;
  return bio11Svg('bio11-fig-2-18', '0 0 1110 360', 'Fig: 2.18 Hydrolysis of ATP molecule', 'ATP (adenosine with three phosphates) is hydrolysed in a reversible reaction to ADP (adenosine with two phosphates) plus one phosphate, releasing 7 kcal of energy.', body, 'background:#fff');
}

function bio11FigCoenzymes() {
  const T = (x, y, s, a = 'start', sz = 20) => `<text x="${x}" y="${y + 6}" font-size="${sz}" fill="#111" text-anchor="${a}" font-family="Arial,sans-serif">${s}</text>`;
  const L = (x1, y1, x2, y2) => `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="#111" stroke-width="1.8"/>`;
  const unit = (x, nadp) => `${T(x, 28, 'P', 'middle', 20)}${L(x + 6, 40, x + 6, 130)}${T(x, 140, 'P', 'middle', 20)}${L(x + 14, 36, x + 98, 74)}${T(x + 112, 82, 'S', 'middle', 20)}${L(x + 120, 74, x + 168, 50)}${T(x + 176, 36, 'Adenine', 'start', 22)}${L(x + 14, 136, x + 98, 164)}${T(x + 112, 172, 'S', 'middle', 20)}${L(x + 120, 164, x + 170, 136)}${T(x + 176, 124, 'Nicotinic Acid', 'start', 22)}${nadp ? `${L(x + 124, 82, x + 172, 98)}${T(x + 182, 104, 'P', 'middle', 20)}` : ''}`;
  const body = `<rect x="4" y="4" width="1100" height="290" fill="#fff" stroke="#111" stroke-width="2"/>
<g transform="translate(40 10)">${unit(0, false)}</g><g transform="translate(580 10)">${unit(0, true)}</g>
${T(150, 245, 'Structure of NAD', 'middle', 22)}${T(700, 245, 'Structure of NADP', 'middle', 22)}`;
  return bio11Svg('bio11-fig-2-19', '0 0 1110 300', 'Fig: 2.19 Some examples of co-enzymes', 'Schematic structures of NAD and NADP: two phosphate groups P joined by sugar units S to an adenine and a nicotinic acid group; NADP carries an extra phosphate on the adenine side.', body, 'background:#fff');
}

