function bio11FigDnaHelix() {
  const cols = { T: '#f3e032', A: '#8bc34a', C: '#c0397a', G: '#e0a0c0' };
  const pairs = [['T', 'A'], ['A', 'T'], ['C', 'G'], ['G', 'C'], ['C', 'G'], ['A', 'T'], ['T', 'A'], ['G', 'C']];
  const rungs = pairs.map(([l, r], i) => { const x = 330 + i * 90; const w = Math.abs(Math.cos(i * 0.9)) * 40 + 10; return `<rect x="${x - 14}" y="${150 - w * 2.2}" width="28" height="${w * 4.4}" fill="${cols[l]}" stroke="#555" stroke-width="1"/><rect x="${x - 14}" y="150" width="28" height="${w * 2.2}" fill="${cols[r]}" stroke="#555" stroke-width="1"/><text x="${x}" y="${150 - w * 1.3}" font-size="13" text-anchor="middle" fill="#111">${l}</text><text x="${x}" y="${150 + w * 1.4}" font-size="13" text-anchor="middle" fill="#111">${r}</text>`; }).join('');
  const strand = (ph, c) => `<path d="${Array.from({ length: 60 }, (_, i) => { const t = i / 59; const x = 90 + t * 940; const y = 150 + Math.sin(t * 5.5 * Math.PI + ph) * 130; return `${i ? 'L' : 'M'}${x.toFixed(1)} ${y.toFixed(1)}`; }).join(' ')}" fill="none" stroke="${c}" stroke-width="26" stroke-linecap="round" opacity=".85"/>`;
  const body = `<rect x="4" y="4" width="1120" height="470" fill="#fff" stroke="#111" stroke-width="2"/>
${strand(0, '#b9b2e0')}${rungs}${strand(Math.PI, '#c8b8e8')}
${bio11SugarText(300, 38, 'Sugar (deoxyribose)', 'start', 20)}${bio11SugarText(320, 66, 'Phosphate group', 'start', 20)}${bio11SugarText(300, 94, 'Sugar-phosphate', 'start', 20)}${bio11SugarText(300, 114, 'backbone', 'start', 20)}
${bio11SugarText(60, 330, 'Weak', 'start', 22)}${bio11SugarText(60, 358, 'hydrogen', 'start', 22)}${bio11SugarText(60, 386, 'bonds', 'start', 22)}
${bio11SugarText(450, 420, 'Nucleotide', 'start', 22)}
${bio11SugarText(30, 420, 'Key', 'start', 22)}${[['Thymine', 'T'], ['Adenine', 'A'], ['Cytosine', 'C'], ['Guanine', 'G']].map(([n, k], i) => `<rect x="30" y="${436 + i * 0}" width="0" height="0"/><rect x="90" y="${392 + i * 18}" width="28" height="14" fill="${cols[k]}" stroke="#555"/>${bio11SugarText(126, 399 + i * 18, n, 'start', 16)}`).join('')}`;
  return bio11Svg('bio11-fig-2-20', '0 0 1130 480', 'Fig: 2.20 Structure of DNA', 'The DNA double helix: two sugar-phosphate backbones twist around each other, held together by weak hydrogen bonds between base pairs (thymine with adenine, cytosine with guanine). A nucleotide consists of a sugar, a phosphate group and a base. A key colours thymine, adenine, cytosine and guanine.', body, 'background:#fff');
}

