    labels: [['Cyclic photophosphorylation', 'چکری فوٹو فاسفوریلیشن', 'حلقوي فوتوفاسفوریلېشن'], ['Photosystem I', 'فوٹو سسٹم I', 'فوتوسیسټم I'], ['Redox chain', 'ریڈاکس زنجیر', 'ریډاکس زنځیر'], ['energy of molecules', 'سالموں کی توانائی', 'د مالیکولونو انرژي'], ['ADP+P', 'ADP+P', 'ADP+P'], ['ATP', 'ATP', 'ATP'], ['Photon', 'فوٹون', 'فوټون']].map(([en, ur, ps]) => ({ en, ur, ps })),
