function bio11FigVirusShapes() {
  const T = (x, y, s, a = 'middle', sz = 22, w = 700, c = '#7a1a1a') => `<text x="${x}" y="${y}" font-size="${sz}" font-weight="${w}" fill="${c}" text-anchor="${a}" font-family="Georgia,serif">${s}</text>`;
  const frame = y => `<rect x="20" y="${y}" width="440" height="190" fill="#c9b0ae" stroke="#222" stroke-width="3"/>`;
  const body = `<rect x="4" y="4" width="470" height="740" fill="#fff" stroke="#222" stroke-width="3"/>
${frame(20)}<g stroke="#f4eeee" stroke-width="8" stroke-linecap="round" fill="none"><path d="M60 170 L260 90"/><path d="M130 130 L170 110"/><path d="M200 70 L260 120 L330 50"/><path d="M260 120 L300 150"/><path d="M360 40 L430 80"/></g>${T(240, 228, 'Tobacco mosaic virus', 'middle', 21)}
${frame(262)}<rect x="20" y="262" width="440" height="190" fill="#f2f2f2"/><g fill="#7da86a">${[[240, 330], [232, 340], [250, 352], [372, 390], [300, 420], [340, 300], [180, 410]].map(([x, y]) => `<circle cx="${x}" cy="${y}" r="3"/>`).join('')}</g><circle cx="240" cy="352" r="12" fill="#cfe2c8" stroke="#6a9a5a" stroke-width="2"/>${T(240, 468, 'Polio virus', 'middle', 21)}
${frame(500)}<rect x="20" y="500" width="440" height="190" fill="#8a6a5c"/><g><path d="M120 560 q-30 -30 0 -50 q40 -10 50 30 q-10 30 -50 20 z" fill="#d97b3a"/><path d="M150 570 L210 620" stroke="#f4eeee" stroke-width="7"/><path d="M340 610 q-20 -40 20 -60 q50 -10 60 40 q-10 40 -60 30 z" fill="#e8582a"/><path d="M350 620 L300 650" stroke="#f4eeee" stroke-width="7"/></g>${T(240, 706, 'Bacteriophage', 'middle', 21)}
${T(240, 735, 'Fig; 5.1 Different Shapes of Viruses', 'middle', 18, 700, '#111')}`;
  return bio11Svg('bio11-fig-5-1', '0 0 480 750', 'Fig; 5.1 Different Shapes of Viruses', 'Three electron micrographs redrawn schematically: tobacco mosaic virus as rod-shaped particles, polio virus as tiny spherical particles, and a bacteriophage as tadpole-shaped particles with a head and a tail.', body, 'background:#fff;max-width:420px');
}

