    labels: [['Tobacco mosaic virus', 'تمباکو موزیک وائرس', 'د تنباکو موزایک ویروس'], ['Polio virus', 'پولیو وائرس', 'پولیو ویروس'], ['Bacteriophage', 'بیکٹیریو فیج', 'باکتریوفاژ']].map(([en, ur, ps]) => ({ en, ur, ps })),
