  flow: [{ type: 'figure', index: 0 }, { type: 'paragraphs', ids: ['bio11-s141-p1', 'bio11-s141-h-c', 'bio11-s141-p2', 'bio11-s141-p3', 'bio11-s141-h-d', 'bio11-s141-p4'] }],
