function bio11FigConjugation() {
  const T = bio11C6.t;
  const cellH = (x, y, w, h, st = '#111') => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${h / 2}" fill="#fff" stroke="${st}" stroke-width="4"/>`;
  const ring = (cx, cy, c1 = '#2a7a4a', c2 = '#b8332a') => `<circle cx="${cx}" cy="${cy}" r="26" fill="none" stroke="${c1}" stroke-width="5" stroke-dasharray="7 3"/><path d="M${cx - 24} ${cy - 10} a26 26 0 0 1 18 -18" stroke="${c2}" stroke-width="5" fill="none"/>`;
  const rr = (cx, cy) => `<circle cx="${cx}" cy="${cy}" r="26" fill="none" stroke="#555" stroke-width="5" stroke-dasharray="7 3"/>`;
  const arrow = y => `<path d="M310 ${y} v34" stroke="#111" stroke-width="4" marker-end="url(#bio11-m68)"/>`;
  const body = `<rect x="3" y="3" width="720" height="580" fill="#fff" stroke="#111" stroke-width="2.4"/>${bio11C6.defs('bio11-m68')}
${cellH(60, 40, 260, 90)}${ring(140, 85)}${T(200, 154, 'Donar cell', 'middle', 15, 700)}
${cellH(330, 40, 250, 90, '#1b2a8a')}${rr(450, 85)}${T(440, 154, 'Recipient cell', 'middle', 15, 700)}
${arrow(160)}
${cellH(60, 230, 260, 90)}${ring(140, 275)}<rect x="318" y="262" width="40" height="26" fill="#eee" stroke="#111" stroke-width="3"/>${cellH(356, 230, 250, 90, '#1b2a8a')}${rr(450, 275)}
${T(230, 350, 'Conjugating tube', 'middle', 15, 700)}<path d="M338 340 V288" stroke="#111" stroke-width="2"/>
${arrow(360)}
${cellH(60, 410, 260, 90)}${ring(140, 455)}<rect x="318" y="442" width="40" height="26" fill="#eee" stroke="#111" stroke-width="3"/>${cellH(356, 410, 250, 90, '#1b2a8a')}${rr(450, 455)}
<path d="M310 520 v22" stroke="#111" stroke-width="4" marker-end="url(#bio11-m68)"/>
${cellH(40, 540, 140, 40)}${ring(110, 560)}${cellH(480, 540, 140, 40)}${rr(550, 560)}
${T(610, 70, 'Donar cell contain', 'start', 13, 700)}${T(610, 86, 'genes that allows', 'start', 13, 700)}${T(610, 102, 'them to transfer some', 'start', 13, 700)}${T(610, 118, 'or all of their', 'start', 13, 700)}${T(610, 134, 'chromosomes to another cell.', 'start', 13, 700)}
${T(130, 214, '2. Conjugation tube connects donar cell to recipient cell. Copy of donar chromosomes begins to move to recipient cell.', 'start', 12, 700)}
${T(130, 395, '3. homologous sections of chromosomes synapse.', 'start', 12, 700)}
${T(190, 575, '4. Cells separate. Section of donar chromosome integrate into recipient chromosome by crossing over.', 'start', 12, 700)}`;
  return bio11Svg('bio11-fig-6-8', '0 0 730 590', 'Fig: 6.8 Bacterial conjugation and recombination', 'Four steps: the donor cell contains genes for transfer; a conjugation tube connects donor and recipient; homologous chromosome sections synapse; the cells separate and a donor section integrates into the recipient chromosome by crossing over.', body, 'background:#fff;max-width:640px');
}

// Schematic drawings standing in for the printed photographs of plant diseases (Figs 6.9–6.13).
function bio11FigPlantDisease(id, kind, caption) {
  const T = bio11C6.t;
  let g = '';
  if (kind === 'spots') g = '<path d="M60 140 q60 -110 160 -80 q50 60 -10 130 q-80 40 -150 -50z" fill="#6aa84f" stroke="#2c5f1d" stroke-width="3"/><path d="M60 140 L215 110" stroke="#2c5f1d" stroke-width="2.4"/>' + [[100,130],[140,100],[170,140],[120,160],[190,115],[150,128]].map(([x, y]) => `<circle cx="${x}" cy="${y}" r="8" fill="#5b3a14" opacity=".85"/>`).join('');
  if (kind === 'wilt') g = '<path d="M140 220 V120" stroke="#2c5f1d" stroke-width="6"/><path d="M140 150 q-50 -10 -70 30 q40 20 70 -10 M140 130 q40 -30 70 10 q-30 30 -70 0 M140 110 q-20 -50 -60 -40 q10 36 60 40" fill="#9dbf6a" stroke="#2c5f1d" stroke-width="3" transform="rotate(8 140 150)"/><path d="M60 230 H220" stroke="#6b4b2a" stroke-width="8"/>';
  if (kind === 'softrot') g = '<ellipse cx="140" cy="140" rx="86" ry="62" fill="#d9b27a" stroke="#6b4b2a" stroke-width="3"/><path d="M96 130 q30 -40 70 -10 q30 30 -4 56 q-40 14 -66 -46z" fill="#5b4326" opacity=".8"/><path d="M160 160 q16 12 30 -2" fill="none" stroke="#3b2a14" stroke-width="3"/>';
  if (kind === 'gall') g = '<path d="M110 40 V230 M170 40 V230" stroke="#6b4b2a" stroke-width="10"/><circle cx="140" cy="130" r="36" fill="#8d6a3c" stroke="#4a3416" stroke-width="3"/><circle cx="118" cy="104" r="14" fill="#8d6a3c" stroke="#4a3416" stroke-width="2.4"/><circle cx="168" cy="158" r="18" fill="#8d6a3c" stroke="#4a3416" stroke-width="2.4"/>';
  if (kind === 'blight') g = '<path d="M50 150 q80 -120 190 -70 q-30 120 -190 70z" fill="#7bb661" stroke="#2c5f1d" stroke-width="3"/><path d="M110 70 q50 20 80 60 q-60 30 -120 10 q20 -40 40 -70z" fill="#b8a14a" opacity=".9"/><path d="M50 150 L240 80" stroke="#2c5f1d" stroke-width="2.4"/>';
  const body = `<rect x="3" y="3" width="274" height="270" fill="#fff" stroke="#111" stroke-width="2"/>${g}${T(140, 262, caption, 'middle', 13, 700)}`;
  return bio11Svg(id, '0 0 280 276', caption, 'Schematic drawing of the plant disease named in the caption (the printed figure is a photograph).', body, 'background:#fff;max-width:300px');
}

const bio11PlantFigNote = { note: 'The printed figure is a photograph; the coded SVG is a simplified schematic drawing carrying the printed caption.' };

// Scan 131 — printed page 140 (folio visible): Fig 6.8 Bacterial conjugation and recombination, E. coli experiment.
bio11Page('bio11-prokaryotes', { scan: 131, printedPage: 140, slug: 'conjugation-fig-6-8', title: 'Fig: 6.8 Bacterial conjugation and recombination · Conjugation experiment', headingUrdu: 'شکل ۶.۸ بیکٹیریائی کنجوگیشن اور ری کمبی نیشن · کنجوگیشن کا تجربہ', headingPashto: 'شکل ۶.۸ باکتریايي کانجوګېشن او ریکامبینېشن · د کانجوګېشن تجربه', auditStatus: 'verified against scan (tilted); folio 140 visible' }, [
  ['p1', 'Normally *Escherichia coli* can synthesize all amino acids it requires. It was exposed to shortwave radiation and two mutants were isolated. One mutant was unable to synthesize biotin (a vitamin) and amino acid methionine. The other mutant could not synthesize amino acids theronine and leucine. The four chemicals are essential for the growth of bacteria. The two mutants were mixed and cultured in a common medium lacking in all the four compounds. None of the cells would have grown in the absence of essential chemicals, but to the great astonishment of researchers, hundreds of colonies of bacteria developed. This suggests that exchange of genes has occurred between two parental bacteria and new recombinants were formed which did not require the four essential compounds for growth. Later studies made by electron microscope confirmed the close contact and the formation of conjugation tube between the parental cells.', 'عام طور پر *Escherichia coli* اپنی ضرورت کے تمام امینو ایسڈز بنا سکتا ہے۔ اسے مختصر موج شعاعوں کے سامنے رکھا گیا اور دو میوٹنٹس الگ کیے گئے۔ ایک میوٹنٹ بایوٹن (ایک وٹامن) اور امینو ایسڈ میتھیونین بنانے سے قاصر تھا۔ دوسرا میوٹنٹ امینو ایسڈز تھریونین اور لیوسین نہیں بنا سکتا تھا۔ یہ چاروں کیمیائی مادے بیکٹیریا کی نشوونما کے لیے ضروری ہیں۔ دونوں میوٹنٹس کو ملا کر ایسے مشترک کلچر میڈیم میں اگایا گیا جس میں چاروں مرکبات موجود نہیں تھے۔ ضروری کیمیائی مادوں کی عدم موجودگی میں کوئی خلیہ نہیں بڑھنا چاہیے تھا، لیکن محققین کی بڑی حیرت کے لیے بیکٹیریا کی سینکڑوں نوآبادیاں پیدا ہو گئیں۔ اس سے ظاہر ہوتا ہے کہ دو والدین بیکٹیریا کے درمیان جینز کا تبادلہ ہوا اور نئے ری کمبیننٹس بنے جنہیں نشوونما کے لیے چاروں ضروری مرکبات کی ضرورت نہیں تھی۔ بعد کے الیکٹران مائیکروسکوپ مطالعات نے والدین خلیوں کے درمیان قریبی رابطے اور کنجوگیشن ٹیوب کے بننے کی تصدیق کی۔', 'په عادي ډول *Escherichia coli* کولای شي ټول هغه امینو اسیدونه جوړ کړي چې ورته اړین دي. دا د لنډو څپو وړانګو سره مخ شو او دوه میوټنټونه جلا شول. یو میوټنټ بایوټین (یو ویټامین) او امینو اسید میتیونین نه شو جوړولای. بل میوټنټ امینو اسیدونه تریونین او لیوسین نه شو جوړولای. دا څلور کیمیاوي مواد د باکتریا د ودې لپاره اړین دي. دواړه میوټنټونه سره ګډ شول او په یو ګډ کلچر منځګړي کې وکرل شول چې د دغو ټولو څلورو مرکباتو څخه تش و. د اړینو کیمیاوي موادو په نشتوالي کې باید هیڅ حجره وده نه وای کړې، خو د څېړونکو د لوی حیرانتیا لپاره د باکتریا سلګونه کالونۍ رامنځته شوې. دا ښيي چې د دوو مورنیو باکتریا ترمنځ د جینونو تبادله شوې او نوي ریکامبینېنټونه جوړ شوي چې د ودې لپاره یې څلورو اړینو مرکباتو ته اړتیا نه درلوده. وروسته د الکترون مایکروسکوپ مطالعاتو د مورنیو حجرو ترمنځ نږدې تماس او د کانجوګېشن نل جوړېدل تایید کړل.', { concept: true, definition: true, editorialNote: 'The scan prints "theronine" (sic, for threonine); preserved as printed. The scan\'s slanted lines are read in natural order.' }]
], {
  figures: [{ id: 'bio11-fig-6-8', svg: bio11FigConjugation(), caption: 'Fig: 6.8 Bacterial conjugation and recombination', captionUrdu: 'شکل ۶.۸ بیکٹیریائی کنجوگیشن اور ری کمبی نیشن', captionPashto: 'شکل ۶.۸ باکتریايي کانجوګېشن او ریکامبینېشن',
    labels: [['Donar cell', 'عطیہ دہندہ خلیہ', 'ورکوونکې حجره'], ['Recipient cell', 'وصول کنندہ خلیہ', 'ترلاسه کوونکې حجره'], ['Donar cell contain genes that allows them to transfer some or all of their chromosomes to another cell.', 'عطیہ دہندہ خلیے میں ایسے جینز ہوتے ہیں جو انہیں اپنے کچھ یا تمام کروموسومز دوسرے خلیے میں منتقل کرنے دیتے ہیں۔', 'ورکوونکې حجره داسې جینونه لري چې دوی ته اجازه ورکوي خپل ځینې یا ټول کروموزومونه بلې حجرې ته ولېږدوي.'], ['2. Conjugation tube connects donar cell to recipient cell. Copy of donar chromosomes begins to move to recipient cell.', '۲۔ کنجوگیشن ٹیوب عطیہ دہندہ خلیے کو وصول کنندہ خلیے سے جوڑتی ہے۔ عطیہ دہندہ کروموسومز کی نقل وصول کنندہ خلیے کی طرف جانا شروع ہوتی ہے۔', '۲. د کانجوګېشن نل ورکوونکې حجره له ترلاسه کوونکې حجرې سره نښلوي. د ورکوونکو کروموزومونو کاپي ترلاسه کوونکې حجرې ته ځي.'], ['Conjugating tube', 'کنجوگیٹنگ ٹیوب', 'کانجوګېټینګ نل'], ['3. homologous sections of chromosomes synapse.', '۳۔ کروموسومز کے ہم شکل حصے جوڑ بناتے ہیں۔', '۳. د کروموزومونو همولوګ برخې سینپس جوړوي.'], ['4. Cells separate. Section of donar chromosome integrate into recipient chromosome by crossing over.', '۴۔ خلیے الگ ہو جاتے ہیں۔ عطیہ دہندہ کروموسوم کا حصہ کراسنگ اوور سے وصول کنندہ کروموسوم میں شامل ہو جاتا ہے۔', '۴. حجرې جلا کېږي. د ورکوونکي کروموزوم برخه د کراسینګ اوور په واسطه د ترلاسه کوونکي کروموزوم سره یوځای کېږي.']].map(([en, ur, ps]) => ({ en, ur, ps })),
    sourceGap: { note: 'The printed figure is a coloured diagram with "Donar" spelled so; preserved. The coded SVG redraws the four stages with the printed labels.' } }],
  flow: [{ type: 'figure', index: 0 }, { type: 'paragraphs', ids: ['bio11-s131-p1'] }],
  inspectedExclusions: [{ kind: 'edge shadow', reason: 'Scanning artefact.' }]
});

// Scan 130 — printed page 141 (folio visible): 6.5 Importance of bacteria, 6.6 Bacterial diseases in humans (intro).
bio11Page('bio11-prokaryotes', { scan: 130, printedPage: 141, slug: 'importance-of-bacteria', title: '6.5 Importance of Bacteria · 6.6 Bacterial Diseases in Humans', headingUrdu: '۶.۵ بیکٹیریا کی اہمیت · ۶.۶ انسانوں میں بیکٹیریائی بیماریاں', headingPashto: '۶.۵ د باکتریا اهمیت · ۶.۶ په انسانانو کې باکتریايي ناروغۍ', auditStatus: 'verified against scan (tilted); folio 141 visible' }, [
  ['h-65', '6.5 Importance of Bacteria', '۶.۵ بیکٹیریا کی اہمیت', '۶.۵ د باکتریا اهمیت', { kind: 'heading', concept: true }],
  ['h-i', 'i. In research technology', 'i۔ تحقیقی ٹیکنالوجی میں', 'i. په څېړنیزه ټیکنالوژۍ کې', { kind: 'subheading', concept: true }],
  ['p1', 'Bacteria are used in biotechnology. For example, *Escherichia coli* are used in gene cloning. *Agrobacterium tumefaciens* is used in producing transgenic plants such as Golden Rice which prevents blindness. Golden Rice contains beta-carotene, a precursor of vitamin A needed for normal vision. Bacteria are modified by genetic engineering to produce vitamins, antibiotics, hormones and other products. Humulin, human insulin is produced by using recombinant DNA technology. It also helps in producing disease resistant crop plants.', 'بیکٹیریا بایوٹیکنالوجی میں استعمال ہوتے ہیں۔ مثلاً *Escherichia coli* جین کلوننگ میں استعمال ہوتا ہے۔ *Agrobacterium tumefaciens* ٹرانس جینک پودے بنانے میں استعمال ہوتا ہے جیسے گولڈن رائس جو اندھے پن کو روکتا ہے۔ گولڈن رائس میں بیٹا کیروٹین ہوتا ہے جو وٹامن A کا پیش رو ہے اور عام بینائی کے لیے ضروری ہے۔ بیکٹیریا کو جینیاتی انجینئرنگ سے تبدیل کیا جاتا ہے تاکہ وہ وٹامنز، اینٹی بایوٹکس، ہارمونز اور دیگر مصنوعات پیدا کریں۔ ہیومیولن، انسانی انسولین، ری کمبیننٹ DNA ٹیکنالوجی سے بنائی جاتی ہے۔ یہ بیماریوں کے خلاف مزاحم فصلی پودے بنانے میں بھی مدد دیتا ہے۔', 'باکتریا په بایوټیکنالوژۍ کې کارول کېږي. د بېلګې په توګه *Escherichia coli* د جین کلونینګ لپاره کارول کېږي. *Agrobacterium tumefaciens* د ټرانسجینیک بوټو جوړولو لپاره کارول کېږي لکه ګولډن رایس چې ړوندوالی مخنیوی کوي. ګولډن رایس بیټا-کاروټین لري چې د ویټامین A مخکښ دی او د عادي لید لپاره اړین دی. باکتریا د جینیټیکي انجینرۍ په واسطه بدلېږي ترڅو ویټامینونه، انټي بایوټیکونه، هورمونونه او نور محصولات تولید کړي. هیومولین، انساني انسولین، د ریکامبینېنټ DNA ټیکنالوژۍ په کارولو سره جوړېږي. دا د ناروغۍ پر وړاندې مقاومو کرنیزو بوټو په جوړولو کې هم مرسته کوي.', { concept: true, definition: true }],
  ['h-ii', 'ii. As nutrient recyclers', 'ii۔ غذائی اجزا کے ری سائیکلر کے طور پر', 'ii. د مغذي موادو د بیا کارونې کوونکو په توګه', { kind: 'subheading', concept: true }],
  ['p2', 'Saprophytic bacteria are decomposers. They break down organic compounds like proteins and carbohydrates into simpler compound like CO_2, which is released in the atmosphere for recycling. It is fixed by green plants in photosynthesis. Other nutrients released in the process enter the soil and become available to plants. Bacteria can decompose the dead remains of plants and animals. Because of their cleaning action they are called the scavengers of planet earth. In sewage treatment, the bacteria bring about the break down of organic compounds and convert them into harmless ions such as nitrates and sulphates.', 'ساپروفائٹک بیکٹیریا تحلیل کار ہیں۔ وہ پروٹینز اور کاربوہائیڈریٹس جیسے نامیاتی مرکبات کو سادہ مرکبات جیسے CO_2 میں توڑ دیتے ہیں جو دوبارہ استعمال کے لیے فضا میں خارج ہوتی ہے۔ اسے سبز پودے ضیائی تالیف میں مستحکم کرتے ہیں۔ اس عمل میں خارج ہونے والے دیگر غذائی اجزا مٹی میں داخل ہو کر پودوں کو دستیاب ہو جاتے ہیں۔ بیکٹیریا پودوں اور جانوروں کی مردہ باقیات کو تحلیل کر سکتے ہیں۔ اپنے صفائی کے عمل کی وجہ سے انہیں کرۂ ارض کے صفائی کارکن کہا جاتا ہے۔ سیوریج کی صفائی میں بیکٹیریا نامیاتی مرکبات کو توڑتے ہیں اور انہیں نائٹریٹس اور سلفیٹس جیسے بے ضرر آئنز میں بدل دیتے ہیں۔', 'سپروفایټیک باکتریا تجزیه کوونکي دي. دوی عضوي مرکبات لکه پروټینونه او کاربوهایډریټونه په ساده مرکباتو لکه CO_2 ماتوي چې د بیا کارونې لپاره په فضا کې خوشې کېږي. دا د شنو بوټو په واسطه په فوتوسنتېز کې تثبیتېږي. په دې بهیر کې خوشې شوي نور مغذي مواد خاورې ته ننوځي او بوټو ته شته کېږي. باکتریا کولای شي د بوټو او څارویو مړه پاتې شونې تجزیه کړي. د خپل پاکوونکي عمل له امله دوی د ځمکې سیارې پاکوونکي بلل کېږي. د مرداره اوبو په درملنه کې باکتریا عضوي مرکبات ماتوي او په بې ضرره آیونونو لکه نایټریټونو او سلفیټونو بدلوي.', { concept: true, definition: true }],
  ['h-iii', 'iii. Role in Ecology', 'iii۔ ماحولیات میں کردار', 'iii. په اکولوژۍ کې رول', { kind: 'subheading', concept: true }],
  ['p3', 'Bacteria play important role in ecological interactions. They are involved in symbiotic nitrogen fixation in the roots of leguminous plants. Herbivorous mammals cannot break down cellulose. Bacteria live in their guts and help in the digestion of cellulose by breaking it down. The relationship is called commensalisms. Soil bacteria decompose the organic matter and make the soil fertile. Bacteria also play important role in nitrogen, phosphorus, sulphur and carbon cycles.', 'بیکٹیریا ماحولیاتی تعاملات میں اہم کردار ادا کرتے ہیں۔ وہ پھلی دار پودوں کی جڑوں میں ہم زیست نائٹروجن استحکام میں شامل ہیں۔ سبزی خور ممالیہ سیلولوز کو نہیں توڑ سکتے۔ بیکٹیریا ان کی آنتوں میں رہتے ہیں اور سیلولوز کو توڑ کر اس کے ہاضمے میں مدد دیتے ہیں۔ اس تعلق کو کامنسلزم کہا جاتا ہے۔ مٹی کے بیکٹیریا نامیاتی مادے کو تحلیل کر کے مٹی کو زرخیز بناتے ہیں۔ بیکٹیریا نائٹروجن، فاسفورس، گندھک اور کاربن کے چکروں میں بھی اہم کردار ادا کرتے ہیں۔', 'باکتریا په اکولوژیکي متقابلو اغېزو کې مهم رول لوبوي. دوی د لوبیایي بوټو په ریښو کې په همژیوي نایتروجن تثبیت کې برخه لري. واښه خوړونکي تی لرونکي سیلولوز نه شي ماتولای. باکتریا د دوی په کولمو کې ژوند کوي او د سیلولوز په ماتولو سره د هغه په هضم کې مرسته کوي. دې اړیکې ته کامینسالیزم ویل کېږي. د خاورې باکتریا عضوي مواد تجزیه کوي او خاوره حاصلخیزه کوي. باکتریا د نایتروجن، فاسفورس، ګوګړو او کاربن په دورو کې هم مهم رول لوبوي.', { concept: true, definition: true, editorialNote: 'The scan prints "commensalisms" (sic); preserved as printed.' }],
  ['h-iv', 'iv. Other uses of bacteria', 'iv۔ بیکٹیریا کے دیگر استعمالات', 'iv. د باکتریا نور کارونې', { kind: 'subheading', concept: true }],
  ['p4', 'Bacteria are used in the preparation of diary products such as butter, cheese and yoghurt. They are involved in the preparation of antibiotics, vinegar, amino acids and proteins. Bacteria are employed in retting of fibers and making of silage.', 'بیکٹیریا ڈیری مصنوعات جیسے مکھن، پنیر اور دہی کی تیاری میں استعمال ہوتے ہیں۔ وہ اینٹی بایوٹکس، سرکہ، امینو ایسڈز اور پروٹینز کی تیاری میں شامل ہیں۔ بیکٹیریا ریشوں کو گلانے (ریٹنگ) اور سائیلج بنانے میں استعمال ہوتے ہیں۔', 'باکتریا د شیدو محصولاتو لکه مکھن، پنیر او مستو په جوړولو کې کارول کېږي. دوی د انټي بایوټیکونو، سرکې، امینو اسیدونو او پروټینونو په جوړولو کې برخه لري. باکتریا د تارونو په ریټینګ او د سایلېج په جوړولو کې کارول کېږي.', { concept: true, editorialNote: 'The scan prints "diary" (for "dairy"); preserved as printed.' }],
  ['h-v', 'v. Spoilage of food', 'v۔ خوراک کا خراب ہونا', 'v. د خوراک خرابېدل', { kind: 'subheading', concept: true }],
  ['p5', 'Bacteria spoil the food items. Foods with high protein contents are decomposed by bacteria. Eggs, fish and cooked food and milk are all spoiled by bacterial action.', 'بیکٹیریا خوراکی اشیا کو خراب کرتے ہیں۔ زیادہ پروٹین والی خوراک بیکٹیریا کے ہاتھوں تحلیل ہو جاتی ہے۔ انڈے، مچھلی اور پکی ہوئی خوراک اور دودھ سب بیکٹیریائی عمل سے خراب ہو جاتے ہیں۔', 'باکتریا خوراکي توکي خرابوي. هغه خوراک چې ډېر پروټین لري د باکتریا په واسطه تجزیه کېږي. هګۍ، کبان او پخه شوې خوراک او شیدې ټول د باکتریايي عمل له امله خرابېږي.', { concept: true }],
  ['h-66', '6.6 Bacterial Diseases in Humans', '۶.۶ انسانوں میں بیکٹیریائی بیماریاں', '۶.۶ په انسانانو کې باکتریايي ناروغۍ', { kind: 'heading', concept: true }],
  ['p6', 'A relatively small number of bacteria are the cause of many serious diseases of human beings. These diseases are transmitted through air, water, food and through wounds or cracks in the skin. Some of the diseases caused by the bacteria are discussed below.', 'بیکٹیریا کی نسبتاً کم تعداد انسانوں کی کئی سنگین بیماریوں کا سبب ہے۔ یہ بیماریاں ہوا، پانی، خوراک اور جلد کے زخموں یا دراڑوں کے ذریعے منتقل ہوتی ہیں۔ بیکٹیریا سے پیدا ہونے والی کچھ بیماریاں ذیل میں بیان کی گئی ہیں۔', 'د باکتریا نسبتاً لږ شمېر د انسانانو د ډېرو جدي ناروغیو لامل دی. دا ناروغۍ د هوا، اوبو، خوراک او د پوټکي د ټپونو یا درزونو له لارې لېږدول کېږي. د باکتریا له امله رامنځته شوې ځینې ناروغۍ لاندې بحث شوي دي.', { concept: true, definition: true }]
], { inspectedExclusions: [{ kind: 'edge shadow and bleed marks', reason: 'Scanning artefact.' }] });

