function bio11FigLichens() {
  let sp = ''; for (let i = 0; i < 60; i++) sp += `<circle cx="${60 + (i * 41) % 180}" cy="${50 + (i * 59) % 170}" r="${4 + i % 4}" fill="${i % 3 ? '#a05a6a' : '#c98fa0'}" opacity=".85"/>`;
  const inner = `<rect x="14" y="14" width="272" height="260" fill="#6aa0c8"/><path d="M40 270 L70 90 q80 -70 150 10 L250 270z" fill="#6b3040" stroke="#3a1420" stroke-width="3"/>${sp}${bio11C7.t(150, 296, 'Fig: 7.12 Lichens on a rock surface', 'middle', 12, 700)}`;
  return bio11C7.box(300, 312, inner, 'bio11-fig-7-12', 'Fig: 7.12 Lichens are common primary colonizers of surfaces', 'Schematic rock surface covered with lichen patches (the printed figure is a photograph).', 300);
}
function bio11FigMildew() {
  const inner = `<rect x="14" y="14" width="232" height="260" fill="#1b1b1b"/><path d="M130 250 q-70 -60 -40 -150 q30 -40 70 0 q30 90 -30 150z" fill="#c9c46a" stroke="#6b6a2a" stroke-width="2.4"/><rect x="108" y="130" width="40" height="36" fill="none" stroke="#d6502a" stroke-width="3"/><path d="M128 168 L190 220" stroke="#d6502a" stroke-width="3"/><rect x="160" y="200" width="70" height="60" fill="#8a7a5a" stroke="#d6502a" stroke-width="3"/>${bio11C7.t(130, 296, 'Fig: 7.13 Powdery mildew on a leaf', 'middle', 12, 700)}`;
  return bio11C7.box(260, 312, inner, 'bio11-fig-7-13', 'Fig: 7.13 Powdery mildew on a leaf', 'Schematic leaf with a boxed patch of powdery mildew and a magnified inset (the printed figure is a photograph).', 260);
}
function bio11FigRingworm() {
  const inner = `<rect x="14" y="14" width="332" height="240" fill="#e8dcd6"/><path d="M40 220 q40 -140 160 -150 q100 10 120 120 q-60 60 -280 30z" fill="#fff" stroke="#bbb" stroke-width="2"/><circle cx="170" cy="150" r="30" fill="#c0507a" opacity=".75"/><circle cx="170" cy="150" r="30" fill="none" stroke="#8a1a4a" stroke-width="3"/><ellipse cx="290" cy="90" rx="30" ry="22" fill="#2a1a14"/><path d="M60 230 q30 -50 90 -20 M40 190 q50 -30 70 20" fill="#e8b8a0" stroke="#a87858" stroke-width="2"/>${bio11C7.t(180, 278, 'Fig: 7.14 Ringworm in dog.', 'middle', 13, 700)}`;
  return bio11C7.box(360, 292, inner, 'bio11-fig-7-14', 'Fig: 7.14 Ringworm in dog.', 'Schematic white-furred dog with a circular red ringworm patch (the printed figure is a photograph).', 360);
}

