function bio11FigBryo(id, caption, kind) {
  const T = bio11C7.t;
  let g = '';
  if (kind === 'march') g = '<path d="M60 190 q-10 -80 70 -90 q70 10 90 60 q-30 70 -110 60z" fill="#7fb06a" stroke="#2c5f1d" stroke-width="3"/><path d="M150 140 l-6 -80 q6 -20 24 -6" fill="none" stroke="#3a2a1a" stroke-width="5"/><circle cx="170" cy="70" r="14" fill="#8a6a50" stroke="#3a2a1a" stroke-width="2"/><path d="M90 160 q40 -30 80 10 M80 180 q50 -20 100 0" stroke="#2c5f1d" stroke-width="2" fill="none"/>';
  else g = [60, 100, 140, 180, 220].map((x, i) => `<path d="M${x} 210 q${i % 2 ? 6 : -6} -70 ${i % 2 ? 4 : -2} -${110 + i * 10}" fill="none" stroke="#3bbf4a" stroke-width="13" stroke-linecap="round"/>`).join('');
  const inner = `<rect x="14" y="14" width="272" height="230" fill="${kind === 'march' ? '#1d3a22' : '#3a5a2a'}"/>${g}${T(150, 272, caption, 'middle', 14, 700)}`;
  return bio11C7.box(300, 286, inner, id, caption, `Schematic of ${kind === 'march' ? 'Marchantia' : 'Anthoceros'} (the printed figure is a photograph).`, 300);
}
function bio11FigFunaria() {
  const inner = `<rect x="14" y="14" width="332" height="190" fill="#0f2430"/>${[60, 120, 180, 240, 290].map((x, i) => `<path d="M${x} 190 q4 -50 ${i % 2 ? 12 : -10} -90" fill="none" stroke="#e5e0b8" stroke-width="3"/><ellipse cx="${x + (i % 2 ? 12 : -10)}" cy="100" rx="8" ry="14" fill="#cfa86a" stroke="#6b4a1a" stroke-width="2"/>`).join('')}<path d="M20 200 q60 -30 120 0 q60 -30 120 0 q60 -30 80 0" fill="#3c8a3c" stroke="#1d4d1d" stroke-width="3"/>${bio11C7.t(180, 232, 'Fig:8.3 Funaria', 'middle', 14, 700)}`;
  return bio11C7.box(360, 246, inner, 'bio11-fig-8-3', 'Fig:8.3 Funaria', 'Schematic Funaria moss plants with spore capsules on stalks (the printed figure is a photograph).', 360);
}
function bio11FigMossCycle() {
  const T = bio11C7.t;
  const dot = (x, y, n) => `<circle cx="${x}" cy="${y}" r="9" fill="#d94a3a"/><text x="${x}" y="${y + 4}" font-size="10" fill="#fff" text-anchor="middle" font-family="Arial,sans-serif" font-weight="700">${n}</text>`;
  const arch = (x, y, egg = true) => `<path d="M${x - 14} ${y + 70} v-60 q0 -22 14 -22 q14 0 14 22 v60z" fill="#cfe5ec" stroke="#2a5d7a" stroke-width="2.4"/>${egg ? `<circle cx="${x}" cy="${y + 54}" r="9" fill="#a8387a"/>` : ''}`;
  const inner = `<defs><marker id="bio11-m84" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#555"/></marker></defs>
<rect x="14" y="14" width="652" height="270" fill="#f7efc0"/><rect x="14" y="284" width="652" height="250" fill="#dfe9ef"/>
${T(30, 150, 'Spores', 'start', 13, 700)}${T(30, 166, '(n)', 'start', 13, 700)}<g fill="#7a4a1a"><circle cx="100" cy="120" r="4"/><circle cx="116" cy="134" r="4"/><circle cx="110" cy="152" r="4"/><circle cx="130" cy="124" r="4"/><circle cx="94" cy="146" r="4"/></g>
${dot(160, 60, '1')}${T(180, 58, 'Mitosis and', 'start', 13, 700)}${T(180, 74, 'development', 'start', 13, 700)}
<path d="M120 120 C190 90 250 70 300 100" fill="none" stroke="#333" stroke-width="2.4" marker-end="url(#bio11-m84)"/>
<g transform="translate(330 180)"><path d="M0 0 l-20 -50 M0 0 l10 -60 M0 0 l30 -40 M0 0 l-12 20 M0 0 l12 20" stroke="#2c7a2c" stroke-width="7"/></g>
${T(310, 250, 'HAPLOID', 'middle', 15, 700)}${T(310, 300, 'DIPLOID', 'middle', 15, 700)}
<path d="M380 150 q50 -30 100 -30" fill="none" stroke="#9c8fb3" stroke-width="14" marker-end="url(#bio11-m84)"/><path d="M380 180 q60 20 100 60" fill="none" stroke="#9c8fb3" stroke-width="14" marker-end="url(#bio11-m84)"/>
${dot(450, 100, '2')}<g fill="#555"><circle cx="520" cy="70" r="3"/><circle cx="530" cy="62" r="3"/><circle cx="540" cy="74" r="3"/></g>${T(556, 66, 'Sperm(n) (released from', 'start', 12, 700)}${T(556, 80, 'their gametangium)', 'start', 12, 700)}
${arch(540, 90)}${T(580, 130, 'Gametangium', 'start', 12, 700)}${T(580, 144, 'containing the egg(n)', 'start', 12, 700)}${T(580, 158, '(remains within', 'start', 12, 700)}${T(580, 172, 'gametophyte)', 'start', 12, 700)}${T(570, 200, 'Egg', 'start', 12, 700)}
<rect x="540" y="262" width="110" height="26" fill="#fff" stroke="#111" stroke-width="2"/>${T(595, 280, 'Fertilization', 'middle', 13, 700)}
<path d="M600 215 C640 240 650 260 640 300" fill="none" stroke="#333" stroke-width="2.4" marker-end="url(#bio11-m84)"/>
${arch(620, 330)}${dot(660, 340, '3')}
<path d="M600 420 C560 460 500 470 440 450" fill="none" stroke="#333" stroke-width="2.4" marker-end="url(#bio11-m84)"/>${dot(520, 470, '4')}
${T(140, 380, 'Sporangium', 'start', 12, 700)}${T(240, 392, 'Stalk', 'start', 12, 700)}
<g stroke="#8a5a1a" fill="#c98a3a" stroke-width="2"><path d="M230 430 q-10 -50 -20 -70" fill="none" stroke-width="3"/><ellipse cx="206" cy="354" rx="8" ry="14"/><path d="M260 430 q4 -60 20 -70" fill="none" stroke-width="3"/><ellipse cx="284" cy="356" rx="8" ry="14"/></g>
<g fill="#2c5f1d"><path d="M180 480 l20 -50 l20 50z M220 490 l20 -60 l20 60z M260 480 l20 -40 l20 40z"/></g>
${T(130, 470, 'Gametophyte', 'end', 12, 700)}${T(130, 484, '(n)', 'end', 12, 700)}
<rect x="30" y="296" width="96" height="26" fill="#fff" stroke="#111" stroke-width="2"/>${T(78, 314, 'Meiosis', 'middle', 13, 700)}
<path d="M110 440 C60 400 60 340 100 300" fill="none" stroke="#333" stroke-width="2.4"/><path d="M80 290 C60 250 80 200 110 175" fill="none" stroke="#333" stroke-width="2.4" marker-end="url(#bio11-m84)"/>${dot(70, 420, '5')}
${T(340, 522, 'Sporophyte (growing from gametophytes)', 'middle', 12, 700)}
${T(340, 556, 'Fig: 8.4 Alternation of generation in a moss plant.', 'middle', 15, 700)}`;
  return bio11C7.box(680, 572, inner, 'bio11-fig-8-4', 'Fig: 8.4 Alternation of generation in a moss plant.', 'Moss life cycle: haploid spores grow by mitosis into the gametophyte; sperm and egg form in gametangia; fertilization gives the diploid sporophyte with sporangium on a stalk; meiosis in the sporangium produces haploid spores.', 680);
}

