      labels: [['Mitosis and development', 'مائٹوسس اور نشوونما', 'مایټوسیس او وده'], ['Spores (n)', 'اسپورز (n)', 'سپورونه (n)'], ['Sperm(n) (released from their gametangium)', 'سپرم (n) (اپنے گیمیٹینجیم سے خارج)', 'سپرم (n) (له خپل ګیمیټانجیم څخه خوشې شوی)'], ['Gametangium containing the egg(n) (remains within gametophyte)', 'گیمیٹینجیم جس میں انڈا (n) ہے (گیمیٹوفائٹ کے اندر رہتا ہے)', 'ګیمیټانجیم چې هګۍ (n) لري (په ګیمیټوفایټ کې پاتې کېږي)'], ['Egg', 'انڈا', 'هګۍ'], ['HAPLOID', 'ہیپلائیڈ', 'هایپلوییډ'], ['DIPLOID', 'ڈپلائیڈ', 'ډیپلوییډ'], ['Fertilization', 'بارآوری', 'بارورې'], ['Meiosis', 'میوسس', 'میوسیس'], ['Sporangium', 'اسپورینجیم', 'سپورانجیم'], ['Stalk', 'ڈنٹھل', 'ډډ'], ['Gametophyte (n)', 'گیمیٹوفائٹ (n)', 'ګیمیټوفایټ (n)'], ['Sporophyte (growing from gametophytes)', 'اسپوروفائٹ (گیمیٹوفائٹس سے اگتا ہوا)', 'سپوروفایټ (له ګیمیټوفایټونو څخه وده کوونکی)']].map(([en, ur, ps]) => ({ en, ur, ps })),
