  flow: [{ type: 'figure', index: 0 }, { type: 'paragraphs', ids: ['bio11-s173-h-c', 'bio11-s173-p1', 'bio11-s173-h-d', 'bio11-s173-p2', 'bio11-s173-h-e', 'bio11-s173-p3'] }],
