      [bio11Cell('Dicots', 'دو بیج پتی', 'دوه لپه'), bio11Cell('Two cotyledons', 'دو کوٹائلیڈنز', 'دوه کوټایلیډونه'), bio11Cell('Veins usually netlike', 'رگیں عموماً جالی نما', 'رګونه معمولاً جالي ډوله'), bio11Cell('Vascular bundles usually arranged in ring', 'عروقی بنڈل عموماً حلقے میں ترتیب شدہ', 'وعايي بنډلونه معمولاً په حلقه کې ترتیب شوي'), bio11Cell('Taproot usually present', 'ٹیپ روٹ عموماً موجود', 'ټاپ ریښه معمولاً شتون لري'), bio11Cell('Floral parts usually in multiples of four or fives', 'پھول کے حصے عموماً چار یا پانچ کے ضعف میں', 'د ګل برخې معمولاً د څلورو یا پنځو په ضرب کې')]
