// Generic labelled-figure helper for Chapter 9: labels are [text, tx, ty, px, py, anchor] (leader line from text to point px,py).
function bio11LabFig(id, w, h, bg, art, labels, caption, alt, maxw = 640) {
  const T = bio11C7.t;
  const ls = labels.map(([s, tx, ty, px, py, a]) => `${T(tx, ty, s, a || 'start', 15, 400)}${px == null ? '' : `<path d="M${tx} ${ty - 5} L${px} ${py}" stroke="#111" stroke-width="1.4" fill="none"/>`}`).join('');
  const inner = `<rect x="14" y="14" width="${w - 28}" height="${h - 70}" fill="${bg}" stroke="#111" stroke-width="2"/>${art}${ls}${T(w / 2, h - 18, caption, 'middle', 15, 700)}`;
  return bio11C7.box(w, h, inner, id, caption, alt, maxw);
}
