  return bio11LabFig('bio11-fig-10-6', 680, 400, '#fff', art, [['Meniscus', 70, 70, 100, 170], ['Air space', 420, 250], ['a', 620, 120, 540, 150], ['b', 620, 150, 530, 165], ['c', 620, 180, 520, 180]], 'Fig: 10.6 Meniscus formation in the xylem', 'A water column showing a U-shaped meniscus beside a leaf cross-section with an air space and water films a, b and c.', 640);
