function bio11FigStomata() {
  const art = `<circle cx="210" cy="260" r="110" fill="#e8f0d0" stroke="#7a8a3a" stroke-width="3"/><path d="M190 190 q-30 70 0 140 q30 -70 0 -140z M230 190 q30 70 0 140 q-30 -70 0 -140z" fill="#fff" stroke="#3a6a1a" stroke-width="3"/><ellipse cx="210" cy="260" rx="16" ry="60" fill="#111"/><circle cx="540" cy="260" r="110" fill="#e8f0d0" stroke="#7a8a3a" stroke-width="3"/><path d="M515 190 q-12 70 0 140 q22 -70 0 -140z M565 190 q12 70 0 140 q-22 -70 0 -140z" fill="#e8f0d0" stroke="#3a6a1a" stroke-width="3"/><path d="M540 190 V330" stroke="#111" stroke-width="5"/>`;
  return bio11LabFig('bio11-fig-10-7', 780, 520, '#fff', art, [['Stoma Opening', 150, 120], ['Guard Cells', 150, 150, 190, 200], ['H2O', 40, 260], ['Vacuole', 320, 230, 240, 240], ['H2O', 340, 260], ['K+', 80, 330], ['H2O', 80, 400], ['H2O', 280, 400], ['Stoma closing', 470, 120], ['H2O', 400, 220], ['H2O', 400, 270], ['H2O', 400, 320], ['H2O', 670, 220], ['H2O', 670, 300]], 'Fig: 10.7 Mechanism of stomatal opening and closing', 'Two guard-cell pairs: with the stoma open (turgid guard cells, water and K+ moving in) and closed (flaccid guard cells, water moving out).', 700);
}

