function bio11FigPhoto2(id, caption, kind) {
  const shapes = {
    sal: '<path d="M120 270 L130 80 M130 140 L90 100 M130 170 L175 120 M128 210 L85 170 M126 230 L170 190" stroke="#9a3a3a" stroke-width="10" stroke-linecap="round" fill="none"/>',
    rhi: Array.from({ length: 16 }, (_, i) => `<path d="M${40 + i * 18} 40 Q${50 + i * 17} 160 ${30 + i * 20} 270" stroke="#8a7a6a" stroke-width="5" fill="none"/>`).join('') + '<rect x="14" y="14" width="332" height="40" fill="#3a7a3a"/>',
    pine: '<ellipse cx="180" cy="130" rx="150" ry="110" fill="#8a4a7a"/><circle cx="180" cy="90" r="30" fill="#bfe8e0"/><path d="M160 250 Q180 200 200 250" fill="#fff"/>'
  };
  const bg = { sal: '#c8b88a', rhi: '#2a2a1a', pine: '#5a8a9a' }[kind];
  const inner = `<rect x="14" y="14" width="332" height="270" fill="${bg}"/>${shapes[kind]}${bio11C7.t(180, 312, caption, 'middle', 13, 700)}`;
  return bio11C7.box(360, 330, inner, id, caption, `Schematic stand-in for the printed photograph "${caption}".`, 340);
}
function bio11FigTurgor() {
  const cell = (x, plasm, label, sub, fill) => `<rect x="${x}" y="120" width="130" height="150" fill="none" stroke="#222" stroke-width="6"/>${plasm ? `<path d="M${x + 40} 160 L${x + 65} 190 L${x + 95} 160 M${x + 65} 190 L${x + 65} 240 L${x + 30} 250" stroke="#8ab83a" stroke-width="6" fill="none"/><ellipse cx="${x + 65}" cy="200" rx="18" ry="24" fill="#2a8ad0"/>` : `<rect x="${x + 6}" y="126" width="118" height="138" fill="#e8d84a" stroke="#8a8a1a" stroke-width="3"/><ellipse cx="${x + 70}" cy="195" rx="${fill}" ry="${fill + 22}" fill="#2a8ad0"/>`}<text x="${x + 65}" y="70" font-size="16" text-anchor="middle" font-family="Arial,sans-serif" fill="#111">${label}</text><text x="${x + 65}" y="310" font-size="16" text-anchor="middle" font-family="Arial,sans-serif" fill="#111">${sub}</text><text x="${x - 20}" y="200" font-size="14" text-anchor="middle" font-family="Arial,sans-serif" fill="#111">H₂O</text>`;
  const art = cell(60, true, 'A. Hypertonic', 'A. Plasmolyzed', 0) + cell(300, false, 'B. Isotonic', 'B. Flaccid', 26) + cell(540, false, 'C. Hypotonic', 'C. Turgid', 40) + `<text x="670" y="130" font-size="13" font-family="Arial,sans-serif" fill="#2a5a9a">Vacuole</text>`;
  return bio11C7.box(740, 360, `<rect x="14" y="14" width="712" height="330" fill="#fff" stroke="#222"/>${art}`, 'bio11-fig-10-15', 'Fig: 10.15 Turgor pressure in different environments', 'Three plant cells with H2O arrows: A hypertonic (plasmolyzed, protoplasm shrunken away from the wall), B isotonic (flaccid), C hypotonic (turgid, large vacuole).', 700);
}

