function bio11FigChailakhian() {
  const pot = (x) => `<path d="M${x} 330 h130 l-14 110 h-102z" fill="#5a2a2a" stroke="#2a1010" stroke-width="3"/>`;
  const plant = (x, bloom) => `<g><path d="M${x + 65} 330 v-120" stroke="#2a5a2a" stroke-width="6"/>${Array.from({ length: 12 }, (_, i) => `<ellipse cx="${x + 65 + (i % 2 ? 50 : -50)}" cy="${310 - i * 12}" rx="42" ry="14" fill="#2a5a2a" transform="rotate(${i % 2 ? -25 : 25} ${x + 65 + (i % 2 ? 50 : -50)} ${310 - i * 12})"/>`).join('')}${bloom ? `<circle cx="${x + 30}" cy="170" r="24" fill="#f5c418"/><circle cx="${x + 110}" cy="180" r="24" fill="#f5c418"/>` : ''}</g>`;
  const inner = `<rect x="14" y="14" width="702" height="500" fill="#fff" stroke="#222" stroke-width="4"/>${plant(80, true)}${pot(100)}${plant(450, false)}${pot(470)}<path d="M430 220 L560 190 L600 215 L450 250z" fill="#3a5ad8"/><path d="M500 190 l-8 -20 M545 188 l8 -22" stroke="#2a5a2a" stroke-width="4"/>
${bio11C7.t(40, 60, 'Long day', 'start', 22, 700)}${bio11C7.t(300, 55, 'Blooms', 'middle', 22, 700)}${bio11C7.t(700, 60, 'Does not bloom', 'end', 22, 700)}${bio11C7.t(700, 90, 'Short day', 'end', 22, 700)}${bio11C7.t(40, 420, 'Short day', 'start', 22, 700)}${bio11C7.t(360, 440, 'Long day', 'start', 22, 700)}${bio11C7.t(365, 540, 'Fig: 10.27 Challakhian experiment on short day plant Chrysanthemum.', 'middle', 16, 700)}`;
  return bio11C7.box(730, 570, inner, 'bio11-fig-10-27', 'Fig: 10.27 Challakhian experiment on short day plant Chrysanthemum.', 'Two potted Chrysanthemum plants. The left plant (labelled Long day at the top and Short day at the bottom) blooms; the right plant, whose upper shoots are covered by a blue shade (labelled Does not bloom, Short day at the top and Long day at the bottom), does not bloom.', 700);
}

