function bio11HeartShape(x, y, s, internal) {
  return `<g transform="translate(${x} ${y}) scale(${s})"><path d="M70 40 q-50 20 -50 90 q10 90 70 120 q70 -30 80 -120 q10 -70 -40 -90 q-30 -10 -60 0z" fill="${internal ? '#f4d8c0' : '#c24a3a'}" stroke="#6a1a1a" stroke-width="3"/><path d="M40 60 q30 -30 60 0 v50 q-30 20 -60 0z" fill="#4a6ad0"/><path d="M110 70 q40 -10 50 30 q-10 40 -50 30z" fill="#d84a3a"/><path d="M50 130 q30 40 40 100 q-20 -20 -40 -100z" fill="#4a6ad0"/><path d="M100 130 q30 40 30 90 q-20 -20 -30 -90z" fill="#d84a3a"/></g>`;
}
function bio11FigHeartExternal() {
  const art = `<path d="M330 250 V120 q0 -50 60 -60 q70 0 70 60 v60 q-40 10 -70 -10 q-20 40 -60 80z" fill="#d83a2a" stroke="#6a1a1a" stroke-width="3"/><rect x="250" y="130" width="60" height="150" rx="14" fill="#4a7ad8" stroke="#1a3a6a" stroke-width="3"/><path d="M370 170 q40 -50 130 -20 l10 40 q-70 -10 -110 40z" fill="#4a7ad8" stroke="#1a3a6a" stroke-width="3"/><path d="M290 250 q-40 60 -10 160 q40 70 140 50 q90 -30 160 -120 q40 -130 -40 -190 q-60 -30 -120 20z" fill="#e0603a" stroke="#6a1a1a" stroke-width="3"/><path d="M270 260 q-40 40 -20 110 q60 60 150 50 q30 -50 -10 -150z" fill="#4a7ad8" stroke="#1a3a6a" stroke-width="2"/><path d="M360 300 q80 -20 130 -120 q50 80 -20 220 q-60 40 -110 20z" fill="#e0502a"/><path d="M320 430 v60" stroke="#4a7ad8" stroke-width="30"/>`;
  return bio11LabFig('bio11-fig-12-1', 920, 780, '#fff', art, [['broachiocephalic trunk', 60, 40, 340, 60], ['left subclavian artery', 560, 30, 450, 50], ['superior vena cava', 130, 100, 280, 140], ['aorta', 620, 110, 450, 100], ['right pulmonary arteries', 20, 175, 260, 190], ['left pulmonary arteries', 620, 190, 500, 185], ['pulmonary trunk', 600, 245, 440, 210], ['right pulmonary veins', 20, 280, 240, 270], ['left pulmonary vein', 600, 290, 500, 270], ['left atrium', 590, 340, 480, 300], ['right atrium', 80, 395, 250, 370], ['left cardiac vein', 580, 395, 420, 340], ['right coronary artery', 40, 470, 300, 400], ['left ventricle', 600, 520, 470, 440], ['right ventricle', 110, 570, 300, 480], ['inferior vena cava', 90, 650, 320, 490], ['Fig: 12.1 Structure of heart', 280, 740]], 'Fig: 12.1 Structure of heart', 'External view of the heart showing the aorta and its branches (brachiocephalic trunk, left subclavian artery), superior and inferior venae cavae, right and left pulmonary arteries and veins, pulmonary trunk, right and left atria, right and left ventricles, right coronary artery and left cardiac vein.', 740);
}
function bio11FigHeartInternal() {
  const art = `<path d="M340 40 q-30 60 -20 140 q90 -20 120 -70 q10 -50 -20 -90z" fill="#e0603a" stroke="#8a2a1a" stroke-width="3"/><path d="M200 70 q-30 60 20 130 l60 20 q20 -80 -10 -150z" fill="#8a6ac0" stroke="#3a2a6a" stroke-width="3"/><path d="M250 240 q-20 100 80 170 q120 20 190 -60 q40 -100 -60 -180 q-100 -60 -210 70z" fill="#f4dcc0" stroke="#8a5a2a" stroke-width="3"/><path d="M265 250 q-20 60 40 120 l70 -20 q10 -80 -30 -130z" fill="#2a4ab0"/><path d="M330 360 q-50 40 -10 90 l90 20 q-30 -60 -80 -110z" fill="#2a4ab0"/><path d="M400 280 q60 -40 120 20 q30 80 -20 140 q-70 20 -110 -60z" fill="#e0502a"/><path d="M420 300 q40 -20 70 20 q10 50 -30 60 q-40 0 -40 -80z" fill="#e87a2a"/>`;
  return bio11LabFig('bio11-fig-12-2', 920, 640, '#fff', art, [['pulmonary valve', 210, 40, 330, 200], ['aorta (arch)', 600, 70, 440, 90], ['pulmonary arteries', 600, 140, 460, 150], ['pulmonary veins', 30, 215, 215, 250], ['left atrium', 590, 260, 500, 300], ['right atrium', 80, 300, 270, 280], ['mitral valve', 590, 330, 430, 330], ['tricuspid valve', 40, 380, 320, 370], ['aortic valve', 600, 430, 440, 340], ['right ventricle', 90, 470, 340, 440], ['left ventricle', 560, 540, 470, 420], ['Fig: 12.2 Internal structure of heart', 280, 610]], 'Fig: 12.2 Internal structure of heart', 'Cut-away view of the heart showing the pulmonary valve, aorta (arch), pulmonary arteries and veins, left and right atria, mitral valve, tricuspid valve, aortic valve and the left and right ventricles.', 740);
}
function bio11FigConduction() {
  const box = (x, y, w, h, t, lines, hdr) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#fff" stroke="#3a8aa8" stroke-width="2"/><rect x="${x}" y="${y}" width="${w}" height="26" fill="${hdr}" opacity=".5"/>${bio11C7.t(x + 8, y + 19, t, 'start', 15, 700)}${lines.map((l, i) => bio11C7.t(x + 8, y + 48 + i * 24, l, 'start', 14, 400)).join('')}`;
  const arrow = (d) => `<path d="${d}" stroke="#d8302a" stroke-width="5" fill="none" marker-end="url(#bio11cdArrow)"/>`;
  const inner = `<defs><marker id="bio11cdArrow" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8z" fill="#d8302a"/></marker></defs><rect x="14" y="14" width="1000" height="860" fill="#fff" stroke="#222" stroke-width="3"/>
${bio11HeartShape(60, 90, 1.1)}${bio11HeartShape(60, 330, 1.1)}${bio11HeartShape(60, 570, 1.1)}${bio11HeartShape(640, 220, 1.1)}${bio11HeartShape(640, 540, 1.1, false)}
${bio11C7.t(110, 80, 'SA node', 'start', 17, 700)}${bio11C7.t(60, 560, 'AV node', 'start', 17, 700)}${bio11C7.t(50, 800, 'AV', 'start', 17, 700)}${bio11C7.t(50, 826, 'bundle', 'start', 17, 700)}${bio11C7.t(200, 804, 'Moderator band', 'start', 17, 700)}${bio11C7.t(300, 770, 'Bundle branches', 'start', 17, 700)}${bio11C7.t(560, 830, 'Purkinje fibers', 'start', 17, 700)}
${box(350, 100, 280, 100, 'STEP 1:', ['SA node activity and atrial', 'activation begin.'], '#cfe8f0')}
${box(350, 350, 280, 130, 'STEP 2:', ['Stimulus spreads across', 'the atrial surfaces and', 'reaches the AV node.', 'activation begin.'], '#cfe8f0')}
${box(350, 640, 280, 140, 'STEP 3:', ['Atrial', 'contraction begins.'], '#f2e8a0')}
${box(700, 140, 290, 200, 'STEP 4:', ['The impulse travels along', 'the interventricular septum', 'within the AV bundle and', 'the bundle branches to the', 'Purkinje fibers and, via the', 'moderator band, to the', 'papilary muscles of the', 'right ventricle.'], '#f2e8a0')}
${box(700, 480, 290, 240, 'STEP 5:', ['The impulse is distributed', 'by Purkinje fibers and', 'relayed throughout the', 'ventricular myocardium.', 'Atrial contraction is', 'completed, and ventricular', 'contraction begins.'], '#f2e8a0')}
${arrow('M490 210 V345')}${arrow('M490 490 V635')}${arrow('M490 790 V840 H680 V120 H840 V135')}${arrow('M840 350 V475')}
${bio11C7.t(500, 868, 'Fig: 12.3 Cardiac Cycle and phases of heartbeat', 'middle', 17, 700)}`;
  return bio11C7.box(1040, 900, inner, 'bio11-fig-12-3', 'Fig: 12.3 Cardiac Cycle and phases of heartbeat', 'Five steps of heart conduction: 1 SA node activity and atrial activation begin; 2 stimulus spreads across the atrial surfaces and reaches the AV node; 3 atrial contraction begins; 4 the impulse travels along the interventricular septum within the AV bundle and bundle branches to the Purkinje fibers and, via the moderator band, to the papillary muscles of the right ventricle; 5 the impulse is distributed by Purkinje fibers throughout the ventricular myocardium, atrial contraction is completed and ventricular contraction begins.', 900);
}

