function bio11FigSkin() {
  const art = `<path d="M170 150 l280 -20 l30 20 v220 l-60 40 h-250z" fill="#e8805a" stroke="#6a2a1a" stroke-width="3"/><path d="M170 150 l280 -20 l30 20 l-280 20z" fill="#d86a4a"/><path d="M180 175 h270 v30 h-270z" fill="#f0c0a8" opacity=".7"/><path d="M270 140 l-8 90 q-10 40 -30 60 M320 130 q10 100 -20 200" stroke="#3a1a0a" stroke-width="10" fill="none"/><circle cx="240" cy="280" r="22" fill="#a86a4a" stroke="#4a2a1a" stroke-width="2"/><path d="M180 360 q120 20 280 -20" stroke="#2a3a8a" stroke-width="7" fill="none"/><g fill="#9ad0e8">${[[190, 310], [230, 340], [330, 330], [400, 330]].map(([x, y]) => `<circle cx="${x}" cy="${y}" r="10"/>`).join('')}</g><ellipse cx="320" cy="320" rx="10" ry="18" fill="#cfe0f0" stroke="#5a7a9a"/>`;
  return bio11LabFig('bio11-fig-13-1', 900, 520, '#fff', art, [['pores', 150, 40, 270, 140], ['hair shaft', 380, 40, 320, 130], ['skin surface sweet pore', 20, 90, 200, 150], ['capillaries', 40, 150, 250, 210], ['erectile muscle', 30, 185, 260, 230], ['sweat gland', 40, 235, 240, 280], ['venule', 90, 305, 230, 320], ['arteriole', 70, 350, 220, 350], ['adipose tissue (fat)', 120, 450, 210, 330], ['nerve ending', 270, 460, 320, 330], ['matrix', 440, 460, 400, 330], ['sebaceous gland', 500, 215, 440, 225], ['epidermis', 650, 120, 480, 150], ['dermis or true skin', 650, 215, 480, 250], ['subcutaneous tissue', 650, 300, 480, 340], ['connective tissue', 550, 400, 470, 385], ['Fig: 13.1 Section of skin', 280, 495]], 'Fig: 13.1 Section of skin', 'Block section of skin showing the epidermis, dermis (true skin) and subcutaneous tissue, with a hair shaft, pores, sweat gland, erectile muscle, capillaries, venule, arteriole, adipose tissue, nerve ending, matrix, sebaceous gland and connective tissue.', 740);
}

