function bio11FigMucusLining() {
  const cells = [60, 130, 200, 330].map((x, i) => `<rect x="${x}" y="120" width="60" height="190" fill="#4aa8d0" stroke="#1a5a7a" stroke-width="2"/><ellipse cx="${x + 30}" cy="${210 + (i % 2) * 20}" rx="9" ry="22" fill="#7a5a6a"/>`).join('');
  const art = `<rect x="20" y="40" width="440" height="50" fill="#d8e8a0" opacity=".8"/><g fill="#8a9a2a">${Array.from({ length: 30 }, (_, i) => `<circle cx="${40 + i * 14}" cy="${60 + (i % 3) * 10}" r="2.5"/>`).join('')}</g>${cells}<rect x="260" y="120" width="70" height="200" rx="26" fill="#6ab04a" stroke="#2a6a1a" stroke-width="3"/><g fill="#4a8a2a">${Array.from({ length: 28 }, (_, i) => `<circle cx="${275 + (i % 4) * 14}" cy="${150 + Math.floor(i / 4) * 22}" r="5"/>`).join('')}</g><g stroke="#223" stroke-width="2.5" fill="none">${Array.from({ length: 16 }, (_, i) => `<path d="M${64 + i * 22} 118 q4 -14 -2 -26"/>`).join('')}</g><rect x="40" y="318" width="420" height="10" fill="#e8c840"/><path d="M420 70 h30" stroke="#4a8ae0" stroke-width="8" marker-end="url(#a)"/>`;
  return bio11LabFig('bio11-fig-13-2', 660, 440, '#fff', art, [['layer of mucus carrying debris', 20, 20, 120, 65], ['coordinated beating of cilia sweeps muscus out of lungs', 300, 20, 400, 60], ['cilia', 10, 108, 70, 110], ['ciliated cell', 10, 210, 70, 210], ['basal lamina', 10, 340, 60, 322], ['basal cell (stem cell)', 70, 372, 120, 300], ['goblet cell (secrete mucus)', 260, 372, 295, 330], ['Fig: 13.2 Mucus lining', 170, 420]], 'Fig: 13.2 Mucus lining', 'Epithelium of the airway: ciliated cells with a layer of mucus carrying debris above them, a goblet cell secreting mucus, basal cells (stem cells) and the basal lamina; coordinated beating of cilia sweeps mucus out of the lungs.', 620);
}
