function bio11FigPyrexia() {
  const steps = ['infection or inflammation', 'leucocytes', 'endogenous pyrogens', 'prostaglandins', 'increase SET POINT', "initiation of 'cold response'", 'increased heat production|decreased heat loss', 'body temperature|at new set point'];
  let y = 20;
  const boxes = steps.map((s, i) => { const l = s.split('|'); const h = l.length > 1 ? 70 : 46; const out = `<rect x="80" y="${y}" width="300" height="${h}" fill="#fff" stroke="#222" stroke-width="2"/>${l.map((t, k) => bio11C7.t(230, y + (l.length > 1 ? 28 + k * 24 : 29), t, 'middle', 16, 400)).join('')}${i < steps.length - 1 ? `<path d="M230 ${y + h} v24" stroke="#222" stroke-width="2" marker-end="url(#bio11pyA)"/>` : ''}`; y += h + 24; return out; }).join('');
  const inner = `<defs><marker id="bio11pyA" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8z" fill="#222"/></marker></defs><rect x="14" y="14" width="440" height="${y + 20}" fill="#fbf6d8"/>${boxes}${bio11C7.t(36, y - 40, 'FEVER', 'start', 18, 700)}${bio11C7.t(240, y + 50, 'Fig: 13.7 Stages in the onset of pyrixia.', 'middle', 15, 700)}`;
  return bio11C7.box(480, y + 70, inner, 'bio11-fig-13-7', 'Fig: 13.7 Stages in the onset of pyrixia.', 'Flow chart: infection or inflammation → leucocytes → endogenous pyrogens → prostaglandins → increase SET POINT → initiation of cold response → increased heat production, decreased heat loss → FEVER: body temperature at new set point.', 440);
}
function bio11FigChildFever() {
  const art = `<rect x="14" y="14" width="330" height="300" fill="#3a2a2a"/><path d="M60 290 q10 -90 100 -120 q100 -30 150 40 l20 80z" fill="#6ab0e0"/><ellipse cx="190" cy="140" rx="85" ry="95" fill="#2a1a1a"/><ellipse cx="190" cy="170" rx="65" ry="75" fill="#f0c8a8"/><path d="M130 130 q60 -50 120 0" stroke="#111" stroke-width="12" fill="none"/><path d="M110 200 q40 -60 100 -50 l-20 70 q-40 10 -80 -20z" fill="#e8b898" stroke="#a87858" stroke-width="2"/><circle cx="165" cy="165" r="6" fill="#222"/><circle cx="215" cy="165" r="6" fill="#222"/><path d="M165 225 q25 -14 50 0" stroke="#7a2a2a" stroke-width="4" fill="none"/>`;
  return bio11C7.box(380, 380, `${art}${bio11C7.t(190, 350, 'Fig:13.6 Fever has certain beneficial aspects too', 'middle', 12, 700)}`, 'bio11-fig-13-6b', 'Fig:13.6 Fever has certain beneficial aspects too', 'Schematic stand-in for the printed photograph of a young child holding a hand to the forehead with a distressed expression.', 340);
}
function bio11FigPolio() {
  const art = `<rect x="14" y="14" width="330" height="250" fill="#4a4a4a"/><path d="M30 130 q80 -80 200 -40 q80 40 80 100 q-60 70 -190 50 q-90 -20 -90 -110z" fill="#7a3a8a"/><circle cx="90" cy="150" r="14" fill="#e87aa8"/><ellipse cx="190" cy="160" rx="60" ry="50" fill="#f0c8a8"/><path d="M250 90 q40 -20 60 20 l-10 50 q-40 -10 -60 -50z" fill="#e8b898" stroke="#a87858" stroke-width="2"/><rect x="225" y="130" width="28" height="12" fill="#ddd" transform="rotate(30 239 136)"/>`;
  return bio11C7.box(380, 330, `${art}${bio11C7.t(190, 300, 'Fig:13.9 Polio vaccine is given against polio virus.', 'middle', 12, 700)}`, 'bio11-fig-13-9', 'Fig:13.9 Polio vaccine is given against polio virus.', 'Schematic stand-in for the printed photograph of an infant in a patterned hood receiving polio vaccine drops by mouth.', 340);
}

